window.HSK30_DICTIONARY_EXAMPLES={"一":{"zh":"一百块。","p":"Yìbǎi kuài.","m":{"uz":"100 yuan.","ru":"100 юаней.","tj":"100 юан."},"source":"course"},"一些":{"zh":"哪个方便一些呢？","p":"Nǎ ge fāngbiàn yìxiē ne?","m":{"uz":"Qaysisi biroz qulayroq?","ru":"Какая немного удобнее?","tj":"Кадомаш каме қулайтар?"},"source":"course"},"一半":{"zh":"差不多一半儿吧。","p":"Chàbuduō yíbànr ba.","m":{"uz":"Taxminan yarmi bo'lsa kerak.","ru":"Наверное, примерно половина.","tj":"Тақрибан нисфаш бошад."},"source":"course"},"一块儿":{"zh":"我们一块儿去公园吧。","p":"Wǒmen yíkuàir qù gōngyuán ba.","m":{"uz":"Keling, parkka birga boramiz.","ru":"Давай вместе пойдём в парк.","tj":"Биёед якҷоя ба боғ равем."},"source":"authored"},"七":{"zh":"大概七八天。","p":"Dàgài qī bā tiān.","m":{"uz":"Taxminan yetti-sakkiz kun.","ru":"Примерно семь-восемь дней.","tj":"Тақрибан ҳафт-ҳашт рӯз."},"source":"course"},"三":{"zh":"三点多。","p":"Sān diǎn duō.","m":{"uz":"Uchdan keyin (taxminan).","ru":"Около трёх (чуть после).","tj":"Каме баъд аз соати се."},"source":"course"},"上去":{"zh":"他们看上去有点儿像。","p":"Tāmen kàn shàngqu yǒudiǎnr xiàng.","m":{"uz":"Ular ko‘rinishidan biroz o‘xshaydi.","ru":"Они на вид немного похожи.","tj":"Онҳо аз рӯйи намуд каме монанданд."},"source":"course"},"上学":{"zh":"上学后，他们都忙了。","p":"Shàngxué hòu, tāmen dōu máng le.","m":{"uz":"Maktab boshlangach, ikkalasi ham band bo‘ladi.","ru":"Когда начнётся школа, оба будут заняты.","tj":"Баъди мактаб сар кардан, ҳар ду банд мешаванд."},"source":"course"},"上来":{"zh":"还有时间，你上来吧。","p":"Hái yǒu shíjiān, nǐ shànglái ba.","m":{"uz":"Hali vaqt bor, sen yuqoriga chiq.","ru":"Время ещё есть, поднимайся ко мне.","tj":"Ҳоло вақт ҳаст, ту боло биё."},"source":"course"},"上课":{"zh":"八点了，该上课了。","p":"Bā diǎn le, gāi shàngkè le.","m":{"uz":"Soat sakkiz bo‘ldi, darsni boshlash vaqti keldi.","ru":"Уже восемь, пора на занятия.","tj":"Соат ҳашт шуд, вақти дарс расид."},"source":"course"},"上面":{"zh":"这上面写着320元。","p":"Zhè shàngmian xiězhe sān bǎi èrshí yuán.","m":{"uz":"Bu yerida 320 yuan deb yozilgan.","ru":"Здесь написано 320 юаней.","tj":"Дар ин ҷо 320 юан навишта шудааст."},"source":"course"},"下":{"zh":"下雨了。","p":"Xià yǔ le.","m":{"uz":"Yomg‘ir yog‘di.","ru":"Пошёл дождь.","tj":"Борон борид."},"source":"course"},"下去":{"zh":"那我一会儿就下去。","p":"Nà wǒ yíhuìr jiù xiàqù.","m":{"uz":"Unda men birozdan keyin tushaman.","ru":"Тогда я через минуту спущусь.","tj":"Пас ман каме баъд поён мефароям."},"source":"course"},"下来":{"zh":"楼上下来几个人。","p":"Lóushàng xiàlái jǐ ge rén.","m":{"uz":"Yuqori qavatdan bir necha kishi tushib keldi.","ru":"Сверху спустились несколько человек.","tj":"Аз боло чанд нафар поён омаданд."},"source":"course"},"下班":{"zh":"同乐，下班吗？","p":"Tónglè, xiàbān ma?","m":{"uz":"Tongle, ishdan chiqdingmi?","ru":"Тунлэ, ты уже закончил работу?","tj":"Тунлэ, аз кор баромадӣ?"},"source":"course"},"下课":{"zh":"今天下课早，你一会儿做什么？","p":"Jīntiān xiàkè zǎo, nǐ yíhuìr zuò shénme?","m":{"uz":"Bugun dars erta tugadi, hozir nima qilasan?","ru":"Сегодня занятия закончились рано, что будешь делать?","tj":"Имрӯз дарс барвақт тамом шуд, ҳозир чӣ мекунӣ?"},"source":"course"},"不久":{"zh":"是啊，时间过得真快，好像是不久前发生的一样。","p":"Shì a, shíjiān guò de zhēn kuài, hǎoxiàng shì bùjiǔ qián fāshēng de yíyàng.","m":{"uz":"Ha, vaqt juda tez o‘tadi, xuddi yaqindagina bo‘lgandek.","ru":"Да, время летит быстро, кажется, будто это случилось совсем недавно.","tj":"Ҳа, вақт хеле зуд мегузарад, гӯё ҳамин наздикӣ рӯй дода бошад."},"source":"course"},"不但":{"zh":"这门课不但有用，而且很有意思！","p":"Zhè mén kè búdàn yǒuyòng, érqiě hěn yǒu yìsi!","m":{"uz":"Bu kurs nafaqat foydali, balki juda qiziqarli ham!","ru":"Этот курс не только полезный, но и очень интересный!","tj":"Ин курс на танҳо муфид, балки хеле ҷолиб ҳам аст!"},"source":"course"},"不同":{"zh":"这两个颜色不同。","p":"Zhè liǎng ge yánsè bùtóng.","m":{"uz":"Bu ikki rang bir xil emas.","ru":"Эти два цвета разные.","tj":"Ин ду ранг аз ҳам фарқ мекунанд."},"source":"authored"},"不好意思":{"zh":"不好意思，天中，我已经到北京了。","p":"Bù hǎoyìsi, Tiānzhōng, wǒ yǐjīng dào Běijīng le.","m":{"uz":"Kechirasan, Tianzhong, men allaqachon Pekinga yetib keldim.","ru":"Извини, Тяньчжун, я уже приехала в Пекин.","tj":"Мебахшӣ, Тянҷун, ман аллакай ба Пекин расидам."},"source":"course"},"不用":{"zh":"不用拿票，刷护照就能检票进站。","p":"Búyòng ná piào, shuā hùzhào jiù néng jiǎnpiào jìnzhàn.","m":{"uz":"Chipta olib yurish shart emas, pasportni skan qilib nazoratdan o‘tib kirish mumkin.","ru":"Билет не нужен: достаточно отсканировать паспорт и пройти контроль.","tj":"Чипта гирифтан шарт нест, шиносномаро скан карда аз назорат мегузарем."},"source":"course"},"不要":{"zh":"表扬千万不要太多。","p":"Biǎoyáng qiānwàn búyào tài duō.","m":{"uz":"Maqtash zinhor haddan tashqari ko'p bo'lmasin.","ru":"Хвалить ни в коем случае нельзя слишком много.","tj":"Таъриф кардан зинҳор аз ҳад зиёд набошад."},"source":"course"},"不见":{"zh":"老师，我听不见。","p":"Lǎoshī, wǒ tīng bu jiàn.","m":{"uz":"Ustoz, eshitmayapman.","ru":"Преподаватель, я не слышу.","tj":"Устод, ман намешунавам."},"source":"course"},"东方":{"zh":"太阳从东方升起。","p":"Tàiyáng cóng dōngfāng shēngqǐ.","m":{"uz":"Quyosh sharqdan chiqadi.","ru":"Солнце встаёт на востоке.","tj":"Офтоб аз шарқ мебарояд."},"source":"authored"},"中学":{"zh":"明年女儿上中学。","p":"Míngnián nǚ'ér shàng zhōngxué.","m":{"uz":"Kelasi yil qizimiz o‘rta maktabga boradi.","ru":"В следующем году дочь пойдёт в среднюю школу.","tj":"Соли оянда духтарамон ба мактаби миёна меравад."},"source":"course"},"中学生":{"zh":"我们家有了一个中学生。","p":"Wǒmen jiā yǒule yí ge zhōngxuéshēng.","m":{"uz":"Oilamizda bitta o‘rta maktab o‘quvchisi bo‘ladi.","ru":"В нашей семье будет ученик средней школы.","tj":"Дар оилаи мо як хонандаи мактаби миёна мешавад."},"source":"course"},"主意":{"zh":"去长城倒是一个好主意。","p":"Qù Chángchéng dào shì yí ge hǎo zhǔyi.","m":{"uz":"Buyuk devorga borish esa yaxshi fikr.","ru":"Съездить на Великую стену - наоборот, хорошая идея.","tj":"Ба Девори бузург рафтан бошад, фикри хуб аст."},"source":"course"},"九":{"zh":"九个小时。","p":"Jiǔ ge xiǎoshí.","m":{"uz":"To‘qqiz soat.","ru":"Девять часов.","tj":"Нӯҳ соат."},"source":"course"},"书包":{"zh":"书包在门后面。","p":"Shūbāo zài mén hòumian.","m":{"uz":"Sumka eshik orqasida.","ru":"Рюкзак за дверью.","tj":"Ҷузвдон пушти дар аст."},"source":"course"},"书店":{"zh":"我们去书店外吧。","p":"Wǒmen qù shūdiàn wài ba.","m":{"uz":"Kitob do‘koni tashqarisiga boraylik.","ru":"Давай пойдём к книжному магазину снаружи.","tj":"Биёед ба беруни мағозаи китоб равем."},"source":"course"},"事":{"zh":"有事吗？","p":"Yǒu shì ma?","m":{"uz":"Biror ish bormi?","ru":"Есть дела?","tj":"Коре ҳаст?"},"source":"course"},"二":{"zh":"二十多岁。","p":"Èrshí duō suì.","m":{"uz":"Yigirma yoshdan oshgan.","ru":"Больше двадцати лет.","tj":"Зиёда аз бист сол."},"source":"course"},"五":{"zh":"下午五点。","p":"Xiàwǔ wǔ diǎn.","m":{"uz":"Tushdan keyin soat beshda.","ru":"В пять часов вечера.","tj":"Соати панҷи баъдазнисфирӯзӣ."},"source":"course"},"从小":{"zh":"我从小就经常跟爸爸跑步，跑步能让人快乐！","p":"Wǒ cóngxiǎo jiù jīngcháng gēn bàba pǎobù, pǎobù néng ràng rén kuàilè!","m":{"uz":"Men bolaligimdan dadam bilan tez-tez yuguraman, yugurish odamni xursand qiladi!","ru":"Я с детства часто бегаю с папой; бег делает людей счастливее!","tj":"Ман аз кӯдакӣ бо падарам зуд-зуд медавам, давидан одамро хушҳол мекунад!"},"source":"course"},"他们":{"zh":"他们读书呢。","p":"Tāmen dú shū ne.","m":{"uz":"Ular hozir kitob o‘qishyapti.","ru":"Они сейчас читают.","tj":"Онҳо ҳоло китоб мехонанд."},"source":"course"},"以上":{"zh":"三个人以上可以买团体票。","p":"Sān ge rén yǐshàng kěyǐ mǎi tuántǐ piào.","m":{"uz":"Uch va undan ortiq kishi guruh chiptasini olishi mumkin.","ru":"Групповой билет могут купить три человека и более.","tj":"Се нафар ва зиёда метавонанд чиптаи гурӯҳӣ харанд."},"source":"authored"},"以为":{"zh":"我还以为是同乐呢，他们看上去有点儿像。","p":"Wǒ hái yǐwéi shì Tónglè ne, tāmen kàn shàngqu yǒudiǎnr xiàng.","m":{"uz":"Men uni Tongle deb o‘ylabman, ular ko‘rinishidan biroz o‘xshaydi.","ru":"А я думал, что это Тунлэ. Они немного похожи.","tj":"Ман гумон кардам Тунлэ аст, онҳо аз рӯйи намуд каме монанданд."},"source":"course"},"以外":{"zh":"除了唱歌以外，他也喜欢跳舞。","p":"Chúle chànggē yǐwài, tā yě xǐhuan tiàowǔ.","m":{"uz":"Qo‘shiq aytishdan tashqari, u raqs tushishni ham yoqtiradi.","ru":"Кроме пения, он также любит танцевать.","tj":"Ба ғайр аз сурудхонӣ, ӯ рақсиданро ҳам дӯст медорад."},"source":"course"},"们":{"zh":"你们好！","p":"Nǐmen hǎo!","m":{"uz":"Hammangizga salom!","ru":"Здравствуйте все!","tj":"Ба ҳамаи шумо салом!"},"source":"course"},"休假":{"zh":"好几个同事都休假了，开会前这么多工作我怕干不完。","p":"Hǎo jǐ ge tóngshì dōu xiūjià le, kāihuì qián zhème duō gōngzuò wǒ pà gàn bu wán.","m":{"uz":"Bir nechta hamkasb ta’tilda, yig‘ilishgacha buncha ishni tugata olmay qolishdan xavotirdaman.","ru":"Несколько коллег в отпуске, боюсь, до совещания не успею закончить столько работы.","tj":"Чанд ҳамкор рухсатӣ аст, метарсам то ҷаласа ин қадар корро тамом карда натавонам."},"source":"course"},"但":{"zh":"有，但车站有点儿远。","p":"Yǒu, dàn chēzhàn yǒudiǎnr yuǎn.","m":{"uz":"Bor, lekin bekat biroz uzoq.","ru":"Есть, но остановка немного далеко.","tj":"Ҳаст, аммо истгоҳ каме дур аст."},"source":"course"},"低":{"zh":"好像发低烧了。","p":"Hǎoxiàng fā dīshāo le.","m":{"uz":"Shekilli, yengil isitmam bor.","ru":"Кажется, небольшая температура.","tj":"Ба назар табам каме баланд шудааст."},"source":"course"},"住院":{"zh":"你怎么突然住院了？大家都很担心你。","p":"Nǐ zěnme tūrán zhùyuàn le? Dàjiā dōu hěn dānxīn nǐ.","m":{"uz":"Nega birdan shifoxonaga yotib qolding? Hamma sendan xavotirda.","ru":"Почему ты вдруг попал в больницу? Все за тебя переживают.","tj":"Чаро ногаҳон дар беморхона бистарӣ шудӣ? Ҳама барои ту хавотиранд."},"source":"course"},"体育馆":{"zh":"天中，最近常看见你来体育馆。","p":"Tiānzhōng, zuìjìn cháng kànjiàn nǐ lái tǐyùguǎn.","m":{"uz":"Tianzhong, so‘nggi paytlarda seni sport zalida tez-tez ko‘ryapman.","ru":"Тяньчжун, в последнее время я часто вижу тебя в спортзале.","tj":"Тянҷун, вақтҳои охир туро зуд-зуд дар толори варзиш мебинам."},"source":"course"},"你好":{"zh":"你好，安妮！","p":"Nǐ hǎo, Ānnī!","m":{"uz":"Salom, Annie!","ru":"Привет, Энни!","tj":"Салом, Энни!"},"source":"course"},"假期":{"zh":"这个假期咱们去哪儿玩玩吧。","p":"Zhège jiàqī zánmen qù nǎr wánwan ba.","m":{"uz":"Bu ta’tilda biror joyga sayrga boraylik.","ru":"Давай куда-нибудь съездим на этих каникулах.","tj":"Дар ин таътил биё ба ягон ҷо сайр равем."},"source":"course"},"做客":{"zh":"谢谢您和叔叔请我来家里做客。","p":"Xièxie nín hé shūshu qǐng wǒ lái jiālǐ zuòkè.","m":{"uz":"Meni uyingizga mehmonga taklif qilganingiz uchun sizga va amakiga rahmat.","ru":"Спасибо вам и дяде, что пригласили меня в гости.","tj":"Раҳмат ба шумо ва амак, ки маро ба хона меҳмон даъват кардед."},"source":"course"},"做法":{"zh":"这种做法很简单。","p":"Zhè zhǒng zuòfǎ hěn jiǎndān.","m":{"uz":"Bu usul juda oddiy.","ru":"Этот способ очень простой.","tj":"Ин усул хеле одӣ аст."},"source":"authored"},"做饭":{"zh":"做饭啊。","p":"Zuò fàn a.","m":{"uz":"Ovqat pishirish-da.","ru":"Готовкой еды.","tj":"Хӯрокпазӣ."},"source":"course"},"充电宝":{"zh":"李文，我的耳机没电了，你有充电宝吗？","p":"Lǐ Wén, wǒ de ěrjī méi diàn le, nǐ yǒu chōngdiànbǎo ma?","m":{"uz":"Li Wen, quloqchinimning quvvati tugadi, powerbanking bormi?","ru":"Ли Вэнь, мои наушники разрядились. У тебя есть пауэрбанк?","tj":"Ли Вэн, гӯшмонакам барқ надорад, пауэрбанк дорӣ?"},"source":"course"},"全":{"zh":"对，这是他从北京出发时，我们全家在机场照的。","p":"Duì, zhè shì tā cóng Běijīng chūfā shí, wǒmen quán jiā zài jīchǎng zhào de.","m":{"uz":"Ha, u Pekindan yo‘lga chiqqan paytda butun oilamiz aeroportda tushgan surat.","ru":"Да, мы всей семьёй сделали её в аэропорту, когда он уезжал из Пекина.","tj":"Ҳа, вақте ӯ аз Пекин ба роҳ баромад, тамоми оила дар фурудгоҳ ин аксро гирифтем."},"source":"course"},"八":{"zh":"一米八几。","p":"Yì mǐ bā jǐ.","m":{"uz":"Bir metr saksoni bir necha santimetr.","ru":"Метр восемьдесят с чем-то.","tj":"Як метру ҳаштоду чанд."},"source":"course"},"公交车":{"zh":"请问，这儿有到北京大学的公交车吗？","p":"Qǐngwèn, zhèr yǒu dào Běijīng Dàxué de gōngjiāochē ma?","m":{"uz":"Kechirasiz, bu yerdan Pekin universitetiga boradigan avtobus bormi?","ru":"Скажите, отсюда есть автобус до Пекинского университета?","tj":"Мебахшед, аз ин ҷо то Донишгоҳи Пекин автобус ҳаст?"},"source":"course"},"六":{"zh":"六点多。","p":"Liù diǎn duō.","m":{"uz":"Oltidan o'tganda.","ru":"Чуть больше шести.","tj":"Каме аз соати шаш гузашта."},"source":"course"},"关机":{"zh":"天中，你的手机怎么关机了？","p":"Tiānzhōng, nǐ de shǒujī zěnme guānjī le?","m":{"uz":"Tianzhong, telefoning nega o‘chiq?","ru":"Тяньчжун, почему у тебя телефон выключен?","tj":"Тянҷун, чаро телефонат хомӯш аст?"},"source":"course"},"关注":{"zh":"我很关注这个问题。","p":"Wǒ hěn guānzhù zhège wèntí.","m":{"uz":"Men bu masalaga katta e’tibor beraman.","ru":"Я уделяю этому вопросу большое внимание.","tj":"Ман ба ин масъала диққати зиёд медиҳам."},"source":"authored"},"兴趣":{"zh":"我对音乐很感兴趣。","p":"Wǒ duì yīnyuè hěn gǎn xìngqù.","m":{"uz":"Men musiqaga juda qiziqaman.","ru":"Мне очень интересна музыка.","tj":"Ман ба мусиқӣ хеле шавқ дорам."},"source":"course"},"养":{"zh":"这只小猫你们养了多久了？","p":"Zhè zhī xiǎomāo nǐmen yǎng le duō jiǔ le?","m":{"uz":"Bu mushukchani qancha vaqtdan beri parvarish qilyapsizlar?","ru":"Как долго вы уже ухаживаете за этим котёнком?","tj":"Ин гурбачаро чанд вақт боз нигоҳубин мекунед?"},"source":"course"},"冬天":{"zh":"我觉得冬天太冷了。","p":"Wǒ juéde dōngtiān tài lěng le.","m":{"uz":"Menimcha, qish juda sovuq.","ru":"Мне кажется, зимой слишком холодно.","tj":"Ба назарам, зимистон хеле хунук аст."},"source":"course"},"冰":{"zh":"这块冰西瓜甜极了。","p":"Zhè kuài bīng xīguā tián jí le.","m":{"uz":"Bu sovutilgan tarvuz nihoyatda shirin.","ru":"Этот охлаждённый арбуз невероятно сладкий.","tj":"Ин тарбузи хунукшуда ниҳоят ширин аст."},"source":"course"},"凉快":{"zh":"今天很凉快。","p":"Jīntiān hěn liángkuai.","m":{"uz":"Bugun havo salqin.","ru":"Сегодня прохладно.","tj":"Имрӯз ҳаво салқин аст."},"source":"authored"},"出去":{"zh":"她跑出去了。","p":"Tā pǎo chū qù le.","m":{"uz":"U yugurib chiqib ketdi.","ru":"Она выбежала (туда).","tj":"Вай давон баромад (он ҷо)."},"source":"course"},"出发":{"zh":"我已经准备好了，可以出发了。","p":"Wǒ yǐjīng zhǔnbèi hǎo le, kěyǐ chūfā le.","m":{"uz":"Men allaqachon tayyorlandim, jo'nashim mumkin.","ru":"Я уже готов, можно выезжать.","tj":"Ман аллакай омода шудам, метавонем ҳаракат кунем."},"source":"course"},"出国":{"zh":"这张照片是李文出国前照的吗？","p":"Zhè zhāng zhàopiàn shì Lǐ Wén chūguó qián zhào de ma?","m":{"uz":"Bu surat Li Wen chet elga ketishidan oldin olinganmi?","ru":"Эта фотография сделана до того, как Ли Вэнь уехал за границу?","tj":"Ин сурат пеш аз ба хориҷ рафтани Ли Вэн гирифта шудааст?"},"source":"course"},"出生":{"zh":"她去年秋天出生的，刚过完一岁生日。","p":"Tā qùnián qiūtiān chūshēng de, gāng guò wán yì suì shēngrì.","m":{"uz":"U o'tgan kuzda tug'ilgan, hozirgina bir yoshini o'tkazdi.","ru":"Она родилась прошлой осенью, только что отметила первый день рождения.","tj":"Ӯ тирамоҳи гузашта таваллуд шудааст, навакак яксолагиашро гузаронд."},"source":"course"},"出门":{"zh":"太好了！出门旅游，多个朋友多条路。","p":"Tài hǎo le! Chūmén lǚyóu, duō ge péngyou duō tiáo lù.","m":{"uz":"Zo‘r! Sayohatga chiqqanda bir do‘st ko‘p bo‘lsa, bir yo‘l ko‘p.","ru":"Отлично! В поездке лишний друг — лишний путь и возможность.","tj":"Олиҷаноб! Дар сафар як дӯст бештар — як роҳ бештар."},"source":"course"},"分开":{"zh":"对，马上就进高铁站了。咱们一起走，别分开。","p":"Duì, mǎshàng jiù jìn gāotiězhàn le. Zánmen yìqǐ zǒu, bié fēnkāi.","m":{"uz":"Ha, hozir vokzal ichiga kiramiz. Birga yuraylik, ajralib ketmaylik.","ru":"Да, скоро войдём на вокзал. Идём вместе, не разделяйся.","tj":"Ҳа, ҳозир ба истгоҳ медароем. Якҷо равем, ҷудо нашавем."},"source":"course"},"刘长春":{"zh":"运动员刘长春参加了奥运会。","p":"Yùndòngyuán Liú Chángchūn cānjiā le Àoyùnhuì.","m":{"uz":"Sportchi Liu Changchun Olimpiya o‘yinlarida qatnashgan.","ru":"Спортсмен Лю Чанчунь участвовал в Олимпийских играх.","tj":"Варзишгар Лю Чанчун дар Бозиҳои олимпӣ иштирок кард."},"source":"authored"},"刚":{"zh":"刚做完，你呢？","p":"Gāng zuòwán, nǐ ne?","m":{"uz":"Hozirgina tugatdim, sen-chi?","ru":"Только что закончил, а ты?","tj":"Ҳозир тамом кардам, ту чӣ?"},"source":"course"},"刚刚":{"zh":"他刚刚来北京两个月。","p":"Tā gānggāng lái Běijīng liǎng ge yuè.","m":{"uz":"U Pekinga kelganiga endigina ikki oy bo‘ldi.","ru":"Он живёт в Пекине всего два месяца.","tj":"Ҳамагӣ ду моҳ шуд, ки ӯ ба Пекин омадааст."},"source":"course"},"初中":{"zh":"她在初中学习英语。","p":"Tā zài chūzhōng xuéxí Yīngyǔ.","m":{"uz":"U o‘rta maktabda ingliz tilini o‘rganadi.","ru":"Она изучает английский в средней школе.","tj":"Ӯ дар мактаби миёна забони англисӣ меомӯзад."},"source":"authored"},"别的":{"zh":"那我们再看看别的。","p":"Nà wǒmen zài kànkan bié de.","m":{"uz":"Unda boshqa narsalarni ko'raylik.","ru":"Тогда посмотрим что-нибудь другое.","tj":"Пас чизҳои дигарро бинем."},"source":"course"},"刮":{"zh":"怎么突然刮起风来了？","p":"Zěnme tūrán guā qǐ fēng lái le?","m":{"uz":"Nega birdan shamol esa boshladi?","ru":"Почему вдруг поднялся ветер?","tj":"Чаро ногаҳон шамол вазидан гирифт?"},"source":"course"},"到处":{"zh":"你怎么还来图书馆学习？同学们都在到处找工作呢。","p":"Nǐ zěnme hái lái túshūguǎn xuéxí? Tóngxuémen dōu zài dàochù zhǎo gōngzuò ne.","m":{"uz":"Nega hali ham kutubxonada o‘qiyapsan? Sinfdoshlar hamma joyda ish qidiryapti-ku.","ru":"Почему ты всё ещё учишься в библиотеке? Однокурсники повсюду ищут работу.","tj":"Чаро ҳоло ҳам дар китобхона мехонӣ? Ҳамсинфон ҳама ҷо кор меҷӯянд."},"source":"course"},"刷":{"zh":"不用拿票，刷护照就能检票进站。","p":"Búyòng ná piào, shuā hùzhào jiù néng jiǎnpiào jìnzhàn.","m":{"uz":"Chipta olib yurish shart emas, pasportni skan qilib nazoratdan o‘tib kirish mumkin.","ru":"Билет не нужен: достаточно отсканировать паспорт и пройти контроль.","tj":"Чипта гирифтан шарт нест, шиносномаро скан карда аз назорат мегузарем."},"source":"course"},"前天":{"zh":"前天我看见家月了，她告诉我你打算继续留学？","p":"Qiántiān wǒ kànjiàn Jiāyuè le, tā gàosu wǒ nǐ dǎsuàn jìxù liúxué?","m":{"uz":"Peshindin Jiayueni ko‘rdim, u sen chet elda o‘qishni davom ettirmoqchi ekaningni aytdi?","ru":"Позавчера я видел Цзяюэ. Она сказала, что ты собираешься продолжить учёбу за границей?","tj":"Пешдирӯз Ҷяюэро дидам, ӯ гуфт ту мехоҳӣ таҳсилро дар хориҷ идома диҳӣ?"},"source":"course"},"前边":{"zh":"学校前边有一家电影院。","p":"Xuéxiào qiánbian yǒu yì jiā diànyǐngyuàn.","m":{"uz":"Maktab oldida bitta kinoteatr bor.","ru":"Перед школой есть кинотеатр.","tj":"Пеши мактаб як кинотеатр ҳаст."},"source":"course"},"办":{"zh":"他出去办事了，下午回来。","p":"Tā chūqu bàn shì le, xiàwǔ huílai.","m":{"uz":"U ish bilan chiqib ketdi, tushdan keyin qaytadi.","ru":"Он вышел по делам, вернётся после обеда.","tj":"Ӯ барои кор баромад, баъд аз нисфирӯзӣ бармегардад."},"source":"course"},"加":{"zh":"好，那再加一个鸡肉，一个……","p":"Hǎo, nà zài jiā yí ge jīròu, yí ge...","m":{"uz":"Xo‘p, unda yana bitta tovuqli taom, yana bitta...","ru":"Хорошо, тогда добавим блюдо из курицы и ещё одно...","tj":"Хуб, пас боз як хӯроки мурғӣ ва яктои дигар..."},"source":"course"},"动":{"zh":"生命在于运动。","p":"Shēngmìng zài yú yùndòng.","m":{"uz":"Hayotning mohiyati harakatdadir.","ru":"Жизнь заключается в движении.","tj":"Зиндагӣ дар ҳаракат аст."},"source":"course"},"动物园":{"zh":"上个月我去了趟北京动物园。","p":"Shàng ge yuè wǒ qù le tàng Běijīng Dòngwùyuán.","m":{"uz":"O'tgan oy Pekin hayvonot bog'iga bir borib keldim.","ru":"В прошлом месяце я съездил в Пекинский зоопарк.","tj":"Моҳи гузашта як бор ба боғи ҳайвоноти Пекин рафтам."},"source":"course"},"勺子":{"zh":"服务员，再给我们拿一双筷子、一个勺子和一个碗。","p":"Fúwùyuán, zài gěi wǒmen ná yì shuāng kuàizi, yí ge sháozi hé yí ge wǎn.","m":{"uz":"Ofitsiant, bizga yana bir juft cho‘pcha, bir qoshiq va bir kosa olib keling.","ru":"Официант, принесите нам ещё одну пару палочек, ложку и миску.","tj":"Пешхизмат, ба мо боз як ҷуфт чӯбча, як қошуқ ва як коса биёред."},"source":"course"},"包子":{"zh":"妈妈，晚饭吃米饭，不想吃包子。","p":"Māma, wǎnfàn chī mǐfàn, bù xiǎng chī bāozi.","m":{"uz":"Oyi, kechki ovqatga guruch yeyman, baozi yegim kelmaydi.","ru":"Мама, на ужин я хочу рис, не хочу баоцзы.","tj":"Оча, барои шом биринҷ мехӯрам, баоцзы хӯрдан намехоҳам."},"source":"course"},"北京南站":{"zh":"我们在北京南站见面吧。","p":"Wǒmen zài Běijīng Nánzhàn jiànmiàn ba.","m":{"uz":"Pekin janubiy vokzalida uchrashamiz.","ru":"Давай встретимся на Южном вокзале Пекина.","tj":"Биёед дар истгоҳи ҷанубии Пекин вохӯрем."},"source":"authored"},"医":{"zh":"他在医院。","p":"Tā zài yīyuàn.","m":{"uz":"U kasalxonada.","ru":"Он в больнице.","tj":"Ӯ дар беморхона аст."},"source":"course"},"十":{"zh":"二十多岁。","p":"Èrshí duō suì.","m":{"uz":"Yigirma yoshdan oshgan.","ru":"Больше двадцати лет.","tj":"Зиёда аз бист сол."},"source":"course"},"午饭":{"zh":"我在学校吃午饭。","p":"Wǒ zài xuéxiào chī wǔfàn.","m":{"uz":"Men maktabda tushlik qilaman.","ru":"Я обедаю в школе.","tj":"Ман дар мактаб хӯроки нисфирӯзӣ мехӯрам."},"source":"course"},"半天":{"zh":"好的，吃一点儿药，今天休息半天吧。","p":"Hǎo de, chī yìdiǎnr yào, jīntiān xiūxi bàn tiān ba.","m":{"uz":"Xo‘p, biroz dori iching, bugun yarim kun dam oling.","ru":"Хорошо, примите немного лекарства и сегодня отдохните полдня.","tj":"Хуб, каме дору гиред ва имрӯз ним рӯз истироҳат кунед."},"source":"course"},"卖":{"zh":"我想卖这本书。","p":"Wǒ xiǎng mài zhè běn shū.","m":{"uz":"Men bu kitobni sotmoqchiman.","ru":"Я хочу продать эту книгу.","tj":"Ман мехоҳам ин китобро фурӯшам."},"source":"authored"},"南京":{"zh":"太好了！你快给我介绍一下南京吧。","p":"Tài hǎo le! Nǐ kuài gěi wǒ jièshào yíxià Nánjīng ba.","m":{"uz":"Zo‘r! Tezroq menga Nanjingni tanishtirib ber.","ru":"Отлично! Расскажи мне скорее о Нанкине.","tj":"Олиҷаноб! Зуд ба ман Нанҷинро муаррифӣ кун."},"source":"course"},"卡":{"zh":"家月，对不起，我昨天忘了还你校园卡了。","p":"Jiāyuè, duìbuqǐ, wǒ zuótiān wàng le huán nǐ xiàoyuánkǎ le.","m":{"uz":"Jiayue, uzr, kecha kampus kartangni qaytarishni unutibman.","ru":"Цзяюэ, прости, я вчера забыл вернуть твою кампус-карту.","tj":"Ҷяюэ, бубахш, дирӯз корти кампусатро баргардонданро фаромӯш кардам."},"source":"course"},"发展":{"zh":"中国发展得很快。","p":"Zhōngguó fāzhǎn de hěn kuài.","m":{"uz":"Xitoy tez rivojlanmoqda.","ru":"Китай быстро развивается.","tj":"Чин босуръат рушд мекунад."},"source":"authored"},"发生":{"zh":"是啊，时间过得真快，好像是不久前发生的一样。","p":"Shì a, shíjiān guò de zhēn kuài, hǎoxiàng shì bùjiǔ qián fāshēng de yíyàng.","m":{"uz":"Ha, vaqt juda tez o‘tadi, xuddi yaqindagina bo‘lgandek.","ru":"Да, время летит быстро, кажется, будто это случилось совсем недавно.","tj":"Ҳа, вақт хеле зуд мегузарад, гӯё ҳамин наздикӣ рӯй дода бошад."},"source":"course"},"受到":{"zh":"他受到大家的欢迎。","p":"Tā shòudào dàjiā de huānyíng.","m":{"uz":"Uni hamma xush ko‘radi.","ru":"Его все радушно принимают.","tj":"Ҳама ӯро хуш пазируфтанд."},"source":"authored"},"变":{"zh":"你没看出来她变了吗？","p":"Nǐ méi kàn chū lái tā biàn le ma?","m":{"uz":"Siz uning o'zgarganini sezmadingizmi?","ru":"Ты разве не заметил, что она изменилась?","tj":"Шумо пай набурдед, ки вай тағйир ёфт?"},"source":"course"},"变成":{"zh":"从那天起，我们就变成了好朋友。","p":"Cóng nà tiān qǐ, wǒmen jiù biànchéng le hǎo péngyou.","m":{"uz":"O‘sha kundan boshlab biz yaxshi do‘st bo‘lib qoldik.","ru":"С того дня мы стали хорошими друзьями.","tj":"Аз ҳамон рӯз мо дӯстони хуб шудем."},"source":"course"},"句":{"zh":"偶尔跟中国人一起唱上几句。","p":"Ǒu'ěr gēn Zhōngguó rén yìqǐ chàng shang jǐ jù.","m":{"uz":"Ba'zan xitoyliklar bilan bir necha misra kuylab qo'yaman.","ru":"Иногда пою несколько строк вместе с китайцами.","tj":"Гоҳ-гоҳ бо чиниҳо чанд ҷумла месароям."},"source":"course"},"只是":{"zh":"你想得太多了！大家打球只是为了锻炼身体。","p":"Nǐ xiǎng de tài duō le! Dàjiā dǎqiú zhǐshì wèile duànliàn shēntǐ.","m":{"uz":"Juda ko‘p o‘ylayapsan! Hamma faqat badan chiniqtirish uchun o‘ynayapti.","ru":"Ты слишком много думаешь! Все играют просто ради физической нагрузки.","tj":"Ту аз ҳад зиёд фикр мекунӣ! Ҳама танҳо барои машқи бадан бозӣ мекунанд."},"source":"course"},"只有":{"zh":"只有努力学习，才能考上大学。","p":"Zhǐyǒu nǔlì xuéxí, cái néng kǎo shàng dàxué.","m":{"uz":"Faqat qattiq o'qisangizgina, universitetga kira olasiz.","ru":"Только усердно учась, можно поступить в университет.","tj":"Танҳо сахт омӯхтан имкон медиҳад ба донишгоҳ дохил шавед."},"source":"course"},"只能":{"zh":"电梯坏了，看来咱们只能走下去了。","p":"Diàntī huài le, kànlái zánmen zhǐ néng zǒu xiàqu le.","m":{"uz":"Lift buzilibdi, ko‘rinishidan piyoda tushishga to‘g‘ri keladi.","ru":"Лифт сломан, похоже, придётся спускаться пешком.","tj":"Лифт вайрон шудааст, ба назар танҳо пиёда поён рафтан мемонад."},"source":"course"},"只要":{"zh":"只要你努力，就能成功！","p":"Zhǐyào nǐ nǔlì, jiù néng chénggōng!","m":{"uz":"Faqat harakat qilsangiz, muvaffaqiyat qozonasiz!","ru":"Только старайся, и добьёшься успеха!","tj":"Танҳо кӯшиш кунед, муваффақ мешавед!"},"source":"course"},"可":{"zh":"打得还可以。","p":"Dǎ de hái kěyǐ.","m":{"uz":"Yomon emas.","ru":"Неплохо.","tj":"Бад не."},"source":"course"},"可是":{"zh":"这可是个大问题，我也不太清楚。","p":"Zhè kě shì ge dà wèntí, wǒ yě bú tài qīngchu.","m":{"uz":"Bu juda katta muammo-ku, men ham aniq bilmayman.","ru":"Это ведь большая проблема, я тоже не очень понимаю.","tj":"Ин воқеан мушкили калон аст, ман ҳам хуб намедонам."},"source":"course"},"右":{"zh":"到路口再往右走。","p":"Dào lùkǒu zài wǎng yòu zǒu.","m":{"uz":"Chorrahaga yetgach o'ngga buriling.","ru":"На перекрёстке поверните направо.","tj":"Ба чорраҳа расидед ба тарафи рост гардед."},"source":"course"},"号码":{"zh":"是一个黑色的箱子，上面写着我的名字和电话号码。","p":"Shì yí ge hēisè de xiāngzi, shàngmian xiězhe wǒ de míngzi hé diànhuà hàomǎ.","m":{"uz":"Qora chamadon, ustida ismim va telefon raqamim yozilgan.","ru":"Это чёрный чемодан, на нём написаны моё имя и номер телефона.","tj":"Ҷомадони сиёҳ аст, рӯяш ному рақами телефонам навишта шудааст."},"source":"course"},"名":{"zh":"你叫什么名字？","p":"Nǐ jiào shénme míngzi?","m":{"uz":"Ismingiz nima?","ru":"Как вас зовут?","tj":"Номи шумо чист?"},"source":"course"},"名人":{"zh":"《名人的故事》？我有这本书。明天我借给你吧。","p":"Míngrén de Gùshi? Wǒ yǒu zhè běn shū. Míngtiān wǒ jiè gěi nǐ ba.","m":{"uz":"“Mashhur insonlar hikoyalari”mi? Menda bu kitob bor. Ertaga senga berib turaman.","ru":"«Истории знаменитых людей»? У меня есть эта книга. Завтра дам тебе.","tj":"«Ҳикояҳои одамони машҳур»? Ин китоб дар ман ҳаст. Фардо ба ту медиҳам."},"source":"course"},"后天":{"zh":"我们今天去、明天去还是后天去？","p":"Wǒmen jīntiān qù, míngtiān qù háishi hòutiān qù?","m":{"uz":"Bugun boramizmi, ertagami yoki indingami?","ru":"Пойдём сегодня, завтра или послезавтра?","tj":"Имрӯз меравем, фардо ё пасфардо?"},"source":"course"},"后年":{"zh":"后年我会去中国学习。","p":"Hòunián wǒ huì qù Zhōngguó xuéxí.","m":{"uz":"Kelasi yildan keyingi yili Xitoyga o‘qishga boraman.","ru":"Через два года я поеду учиться в Китай.","tj":"Пас аз ду сол барои таҳсил ба Чин меравам."},"source":"authored"},"听见":{"zh":"同学们都没听见。","p":"Tóngxuémen dōu méi tīngjiàn.","m":{"uz":"Talabalarning hech biri eshitmadi.","ru":"Студенты все не услышали.","tj":"Ҳеҷ кадом аз донишҷӯён нашуниданд."},"source":"course"},"听说":{"zh":"没看过，听说很有意思。","p":"Méi kànguo, tīngshuō hěn yǒu yìsi.","m":{"uz":"Ko'rmaganman, eshitishimcha juda qiziqarli emish.","ru":"Не смотрел(а), говорят, очень интересный.","tj":"Надидаам, гуфтанд хеле ҷолиб аст."},"source":"course"},"员":{"zh":"服务员，我房间的门打不开了。","p":"Fúwùyuán, wǒ fángjiān de mén dǎ bù kāi le.","m":{"uz":"Ofitsiant, xonamning eshigi ochmayapti.","ru":"Сотрудник, дверь моего номера не открывается.","tj":"Хизматрасон, дари хонаи ман намекушояд."},"source":"course"},"咱们":{"zh":"咱们可以走着去。","p":"Zánmen kěyǐ zǒuzhe qù.","m":{"uz":"Biz piyoda bora olamiz.","ru":"Мы можем пойти пешком.","tj":"Мо метавонем пиёда равем."},"source":"course"},"哈哈":{"zh":"哈哈，你说得真有意思！","p":"Hāhā, nǐ shuō de zhēn yǒuyìsi!","m":{"uz":"Ha-ha, gaping juda qiziq ekan!","ru":"Ха-ха, ты так интересно говоришь!","tj":"Ҳа-ҳа, гапат хеле шавқовар аст!"},"source":"authored"},"哪个":{"zh":"哪个菜都好吃。","p":"Nǎge cài dōu hǎochī.","m":{"uz":"Qaysi taomni olsang ham mazali.","ru":"Любое блюдо вкусное.","tj":"Ҳар кадом хӯрок болаззат аст."},"source":"course"},"哪些":{"zh":"你喜欢哪些水果？","p":"Nǐ xǐhuan nǎxiē shuǐguǒ?","m":{"uz":"Qaysi mevalarni yoqtirasan?","ru":"Какие фрукты тебе нравятся?","tj":"Кадом меваҳоро дӯст медорӣ?"},"source":"authored"},"哪里":{"zh":"去哪里？","p":"Qù nǎli?","m":{"uz":"Qayerga?","ru":"Куда?","tj":"Ба куҷо?"},"source":"course"},"售货员":{"zh":"售货员正在给我介绍这件衣服。","p":"Shòuhuòyuán zhèngzài gěi wǒ jièshào zhè jiàn yīfu.","m":{"uz":"Sotuvchi menga bu kiyimni tushuntiryapti.","ru":"Продавец рассказывает мне об этой одежде.","tj":"Фурӯшанда ин либосро ба ман муаррифӣ мекунад."},"source":"authored"},"唱":{"zh":"你们唱了多久？","p":"Nǐmen chàng le duō jiǔ?","m":{"uz":"Qancha vaqt qo'shiq aytdinglar?","ru":"Как долго вы пели?","tj":"Чанд вақт суруд хондед?"},"source":"course"},"商场":{"zh":"商场不远，咱们可以走着去。","p":"Shāngchǎng bù yuǎn, zánmen kěyǐ zǒuzhe qù.","m":{"uz":"Savdo markazi uzoq emas, piyoda borsak bo‘ladi.","ru":"Торговый центр недалеко, можем пойти пешком.","tj":"Маркази савдо дур нест, пиёда рафтан мумкин."},"source":"course"},"喜爱":{"zh":"我很喜爱中国文化。","p":"Wǒ hěn xǐ'ài Zhōngguó wénhuà.","m":{"uz":"Men Xitoy madaniyatini juda yaxshi ko‘raman.","ru":"Я очень люблю китайскую культуру.","tj":"Ман фарҳанги Чинро хеле дӯст медорам."},"source":"authored"},"四":{"zh":"今天星期四。","p":"Jīntiān Xīngqīsì.","m":{"uz":"Bugun payshanba.","ru":"Сегодня четверг.","tj":"Имрӯз панҷшанбе аст."},"source":"course"},"四季":{"zh":"这一年多住下来，我还是更喜欢北京的四季。","p":"Zhè yì nián duō zhù xiàlái, wǒ háishi gèng xǐhuan Běijīng de sìjì.","m":{"uz":"Bir yildan oshiq yashab ko‘rib, baribir Pekinning to‘rt faslini ko‘proq yoqtiraman.","ru":"Прожив здесь больше года, я всё же больше люблю четыре сезона Пекина.","tj":"Зиёда аз як сол зиндагӣ карда, ман ҳоло ҳам чор фасли Пекинро бештар дӯст медорам."},"source":"course"},"回去":{"zh":"我们打车回去吧。","p":"Wǒmen dǎchē huíqù ba.","m":{"uz":"Uyga taksida qaytaylik.","ru":"Давай поедем обратно на такси.","tj":"Биё бо таксӣ ба хона баргардем."},"source":"course"},"国宝":{"zh":"大熊猫为什么是中国的国宝？","p":"Dàxióngmāo wèishénme shì Zhōngguó de guóbǎo?","m":{"uz":"Nega katta panda Xitoyning milliy boyligi hisoblanadi?","ru":"Почему большая панда считается национальным достоянием Китая?","tj":"Чаро пандаи калон сарвати миллии Чин аст?"},"source":"course"},"地点":{"zh":"请告诉我见面的地点。","p":"Qǐng gàosu wǒ jiànmiàn de dìdiǎn.","m":{"uz":"Iltimos, uchrashadigan joyni ayting.","ru":"Пожалуйста, скажите, где мы встречаемся.","tj":"Лутфан, ҷои вохӯриро бигӯед."},"source":"authored"},"坚持":{"zh":"只要坚持下去，就能成功！","p":"Zhǐyào jiānchí xià qù, jiù néng chénggōng!","m":{"uz":"Faqat davom etsangiz, muvaffaqiyat qozonasiz!","ru":"Только продолжай — и добьёшься успеха!","tj":"Танҳо идома диҳед, муваффақ мешавед!"},"source":"course"},"声":{"zh":"音乐的声音合适吗？","p":"Yīnyuè de shēngyīn héshì ma?","m":{"uz":"Musiqa ovozi mosmi?","ru":"Громкость музыки нормальная?","tj":"Баландии мусиқӣ мувофиқ аст?"},"source":"course"},"夏天":{"zh":"今年夏天热极了。","p":"Jīnnián xiàtiān rè jí le.","m":{"uz":"Bu yoz nihoyatda issiq.","ru":"Этим летом ужасно жарко.","tj":"Имсол тобистон ниҳоят гарм аст."},"source":"course"},"外卖":{"zh":"他们家还能送外卖？","p":"Tāmen jiā hái néng sòng wàimài?","m":{"uz":"Ular yetkazib berish ham qiladimi?","ru":"У них ещё и доставка есть?","tj":"Онҳо хӯрокро расонида ҳам медиҳанд?"},"source":"course"},"外国":{"zh":"第一次请外国朋友来家里过春节，我也很高兴。","p":"Dì yí cì qǐng wàiguó péngyou lái jiālǐ guò Chūnjié, wǒ yě hěn gāoxìng.","m":{"uz":"Chet ellik do‘stimni uyga Bahor bayramiga birinchi marta taklif qilyapman, men ham juda xursandman.","ru":"Я впервые приглашаю иностранного друга домой на Праздник Весны и тоже очень рад.","tj":"Бори аввал дӯсти хориҷиро ба хона барои Иди Баҳор даъват мекунам, ман ҳам хеле хушҳолам."},"source":"course"},"外地":{"zh":"我要跟周经理去外地办事，明天的飞机。","p":"Wǒ yào gēn Zhōu jīnglǐ qù wàidì bàn shì, míngtiān de fēijī.","m":{"uz":"Men menejer Zhou bilan boshqa joyga ishga boraman, ertaga samolyot.","ru":"Я еду с менеджером Чжоу в другой город по делам, самолёт завтра.","tj":"Ман бо мудир Чжоу ба ҷои дигар барои кор меравам, ҳавопаймо пагоҳ аст."},"source":"course"},"外语":{"zh":"上海话听起来就像外语一样。","p":"Shànghǎihuà tīng qǐlai jiù xiàng wàiyǔ yíyàng.","m":{"uz":"Shanxaycha eshitilganda xuddi chet tiliga o'xshaydi.","ru":"Шанхайский диалект на слух похож на иностранный язык.","tj":"Лаҳҷаи Шанхай ҳангоми шунидан мисли забони хориҷӣ менамояд."},"source":"course"},"外边":{"zh":"外边冷，我们进房间吧。","p":"Wàibian lěng, wǒmen jìn fángjiān ba.","m":{"uz":"Tashqari sovuq, xonaga kiraylik.","ru":"На улице холодно, давай зайдём в комнату.","tj":"Берун сард аст, биёем ба хона дарем."},"source":"course"},"大人":{"zh":"这个公园里，大人和孩子都能玩。","p":"Zhège gōngyuán lǐ, dàren hé háizi dōu néng wán.","m":{"uz":"Bu parkda kattalar ham, bolalar ham o‘ynay oladi.","ru":"В этом парке могут играть и взрослые, и дети.","tj":"Дар ин боғ ҳам калонсолон ва ҳам кӯдакон бозӣ карда метавонанд."},"source":"authored"},"大学生":{"zh":"对，我读大学呢，还是大学生。","p":"Duì, wǒ dú dàxué ne, hái shì dàxuéshēng.","m":{"uz":"Ha, universitetda o‘qiyman, hali talabaman.","ru":"Да, я учусь в университете, я ещё студент.","tj":"Ҳа, дар донишгоҳ мехонам, ҳоло ҳам донишҷӯ ҳастам."},"source":"course"},"大小":{"zh":"大小没关系，主要是环境，哪个更安静？","p":"Dàxiǎo méi guānxi, zhǔyào shì huánjìng, nǎ ge gèng ānjìng?","m":{"uz":"Kattaligi muhim emas, asosiysi muhit, qaysisi tinchroq?","ru":"Размер не важен, главное окружение, где тише?","tj":"Андоза муҳим нест, асосӣ муҳит аст, кадомаш оромтар?"},"source":"course"},"大熊猫":{"zh":"大熊猫的生活真舒服啊！","p":"Dàxióngmāo de shēnghuó zhēn shūfu a!","m":{"uz":"Pandalarning hayoti rostdan ham mazza ekan!","ru":"Какая же комфортная жизнь у панд!","tj":"Зиндагии пандаҳо воқеан роҳат аст!"},"source":"course"},"大衣":{"zh":"我回去穿上运动鞋，拿上大衣。要不要叫一雪姐一起去？","p":"Wǒ huíqu chuān shàng yùndòngxié, ná shàng dàyī. Yào bú yào jiào Yīxuě jiě yìqǐ qù?","m":{"uz":"Men qaytib sport oyoq kiyimimni kiyaman, paltomni olaman. Yixue opani ham chaqiraylikmi?","ru":"Я схожу переобуюсь в спортивную обувь и возьму пальто. Позвать сестру Исюэ с нами?","tj":"Ман бармегардам, пойафзоли варзишӣ мепӯшам ва палторо мегирам. Апаи Исюэро ҳам даъват кунем?"},"source":"course"},"天":{"zh":"住三天。","p":"Zhù sān tiān.","m":{"uz":"Uch kun.","ru":"Три дня.","tj":"Се рӯз."},"source":"course"},"夫妻":{"zh":"这对夫妻每天一起散步。","p":"Zhè duì fūqī měitiān yìqǐ sànbù.","m":{"uz":"Bu er-xotin har kuni birga sayr qiladi.","ru":"Эти супруги каждый день гуляют вместе.","tj":"Ин зану шавҳар ҳар рӯз якҷоя сайр мекунанд."},"source":"authored"},"头":{"zh":"我头疼，不太舒服。","p":"Wǒ tóu téng, bú tài shūfu.","m":{"uz":"Boshim og‘riyapti, o‘zimni yaxshi his qilmayapman.","ru":"У меня болит голова, я не очень хорошо себя чувствую.","tj":"Сарам дард мекунад, худро хуб ҳис намекунам."},"source":"course"},"奥运会":{"zh":"运动员刘长春参加了奥运会。","p":"Yùndòngyuán Liú Chángchūn cānjiā le Àoyùnhuì.","m":{"uz":"Sportchi Liu Changchun Olimpiya o‘yinlarida qatnashgan.","ru":"Спортсмен Лю Чанчунь участвовал в Олимпийских играх.","tj":"Варзишгар Лю Чанчун дар Бозиҳои олимпӣ иштирок кард."},"source":"authored"},"女士":{"zh":"女士，请坐！您喝什么？","p":"Nǚshì, qǐng zuò! Nín hē shénme?","m":{"uz":"Xonim, marhamat o‘tiring! Nima ichasiz?","ru":"Госпожа, присаживайтесь! Что будете пить?","tj":"Хонум, марҳамат нишинед! Чӣ менӯшед?"},"source":"course"},"女孩儿":{"zh":"那个女孩儿又高又漂亮。","p":"Nàge nǚháir yòu gāo yòu piàoliang.","m":{"uz":"U qiz ham baland bo‘yli, ham chiroyli.","ru":"Та девушка и высокая, и красивая.","tj":"Он духтар ҳам қадбаланд аст, ҳам зебо."},"source":"course"},"女朋友":{"zh":"这是我女朋友。","p":"Zhè shì wǒ nǚpéngyou.","m":{"uz":"Bu mening qiz do‘stim.","ru":"Это моя девушка.","tj":"Ин дӯстдухтари ман аст."},"source":"course"},"女生":{"zh":"知道，我和几个女生要表演一个节目。你也参加吗？","p":"Zhīdào, wǒ hé jǐ ge nǚshēng yào biǎoyǎn yí ge jiémù. Nǐ yě cānjiā ma?","m":{"uz":"Bilaman, men bir nechta qiz bilan bir chiqish tayyorlayapman. Sen ham qatnashasanmi?","ru":"Знаю, я с несколькими девушками готовлю номер. Ты тоже участвуешь?","tj":"Медонам, ман бо чанд духтар як барнома иҷро мекунем. Ту ҳам иштирок мекунӣ?"},"source":"course"},"奶茶":{"zh":"不是，奶茶是爷爷买的。","p":"Bú shì, nǎichá shì yéye mǎi de.","m":{"uz":"Yo‘q, sutli choyni bobo sotib olgan.","ru":"Нет, чай с молоком купил дедушка.","tj":"Не, чойи шириро бобо харидааст."},"source":"course"},"她们":{"zh":"爸，妈，这是白家月，这是安妮。她们都是一飞的学生。","p":"Bà, mā, zhè shì Bái Jiāyuè, zhè shì Ānnī. Tāmen dōu shì Yīfēi de xuésheng.","m":{"uz":"Dada, oyi, bu Bai Jiayue, bu Annie. Ikkalasi ham Yifeining talabalari.","ru":"Папа, мама, это Бай Цзяюэ, а это Энни. Они обе ученицы Ифэй.","tj":"Дада, оча, ин Бай Ҷяюэ, ин Энни. Ҳарду донишҷӯи Ифэй ҳастанд."},"source":"course"},"好久":{"zh":"这个主意好！我好久没骑马了。","p":"Zhège zhǔyi hǎo! Wǒ hǎojiǔ méi qí mǎ le.","m":{"uz":"Bu yaxshi fikr! Anchadan beri ot minmaganman.","ru":"Хорошая идея! Я давно не ездил верхом.","tj":"Ин фикр хуб аст! Кайҳо аспсаворӣ накардаам."},"source":"course"},"好像":{"zh":"好像发低烧了。","p":"Hǎoxiàng fā dīshāo le.","m":{"uz":"Shekilli, yengil isitmam bor.","ru":"Кажется, небольшая температура.","tj":"Ба назар табам каме баланд шудааст."},"source":"course"},"好听":{"zh":"你唱歌很好听。","p":"Nǐ chànggē hěn hǎotīng.","m":{"uz":"Sen juda chiroyli kuylaysan.","ru":"Ты очень хорошо поёшь.","tj":"Ту хеле хуш месароӣ."},"source":"course"},"好多":{"zh":"你比我好多了！","p":"Nǐ bǐ wǒ hǎo duō le!","m":{"uz":"Siz mendan ancha yaxshisiz!","ru":"Ты намного лучше меня!","tj":"Шумо аз ман хеле беҳтаред!"},"source":"course"},"好玩儿":{"zh":"北京比这儿更好玩儿。","p":"Běijīng bǐ zhèr gèng hǎo wánr.","m":{"uz":"Pekin bu yerdan yanada qiziqarliroq.","ru":"В Пекине ещё интереснее, чем здесь.","tj":"Пекин аз ин ҷо боз ҳам ҷолибтар аст."},"source":"course"},"好看":{"zh":"真好看！","p":"Zhēn hǎokàn!","m":{"uz":"Juda chiroyli ekan!","ru":"Очень красивый!","tj":"Хеле зебо будааст!"},"source":"course"},"姓名":{"zh":"请告诉我您的姓名。","p":"Qǐng gàosu wǒ nín de xìngmíng.","m":{"uz":"Iltimos, ism-familiyangizni ayting.","ru":"Пожалуйста, назовите ваши имя и фамилию.","tj":"Лутфан, ному насаби худро гӯед."},"source":"authored"},"学":{"zh":"我去学校。","p":"Wǒ qù xuéxiào.","m":{"uz":"Men maktabga boraman.","ru":"Я иду в школу.","tj":"Ман ба мактаб мераваm."},"source":"course"},"学期":{"zh":"还有最后一个学期就要毕业了，他很快就会回来了。","p":"Hái yǒu zuìhòu yí ge xuéqī jiù yào bìyè le, tā hěn kuài jiù huì huílái le.","m":{"uz":"Faqat oxirgi bir semestr qoldi, keyin bitiradi va tez orada qaytadi.","ru":"Остался последний семестр до выпуска, скоро он вернётся.","tj":"Танҳо як семестри охир мондааст, баъд хатм мекунад ва зуд бармегардад."},"source":"course"},"它们":{"zh":"好的，我马上就去把它们扔掉。","p":"Hǎo de, wǒ mǎshàng jiù qù bǎ tāmen rēngdiào.","m":{"uz":"Xo'p, hoziroq borib ularni tashlab yuboraman.","ru":"Хорошо, сейчас же выброшу их.","tj":"Хуб, ҳозир онҳоро мепартоям."},"source":"course"},"客气":{"zh":"不客气。","p":"Bú kèqi.","m":{"uz":"Arzimaydi.","ru":"Не за что.","tj":"Марҳамат."},"source":"course"},"室":{"zh":"他还在教室学习呢。","p":"Tā hái zài jiàoshì xuéxí ne.","m":{"uz":"U hali darsxonada o'qiyapti.","ru":"Он ещё занимается в классе.","tj":"Вай ҳанӯз дар синфхона дарс мехонад."},"source":"course"},"家人":{"zh":"那你跟家人会一起做什么？","p":"Nà nǐ gēn jiārén huì yìqǐ zuò shénme?","m":{"uz":"Unda oilang bilan birga nimalar qilasizlar?","ru":"А что вы обычно делаете вместе с семьёй?","tj":"Пас бо оилаатон якҷо чӣ кор мекунед?"},"source":"course"},"对话":{"zh":"书上第五页的这个对话我看不懂，小雪也不明白。","p":"Shū shàng dì wǔ yè de zhège duìhuà wǒ kàn bu dǒng, Xiǎoxuě yě bù míngbai.","m":{"uz":"Kitobning beshinchi sahifasidagi bu dialogni tushunmayapman, Xiaoxue ham tushunmadi.","ru":"Я не понимаю диалог на пятой странице, Сяосюэ тоже.","tj":"Муколамаи саҳифаи панҷумро намефаҳмам, Сяосюэ ҳам намефаҳмад."},"source":"course"},"封":{"zh":"我给朋友写了一封信。","p":"Wǒ gěi péngyou xiě le yì fēng xìn.","m":{"uz":"Do‘stimga bitta xat yozdim.","ru":"Я написал другу одно письмо.","tj":"Ман ба дӯстам як нома навиштам."},"source":"authored"},"小区":{"zh":"这个小区环境挺好的。","p":"Zhège xiǎoqū huánjìng tǐng hǎo de.","m":{"uz":"Bu turar-joy majmuasining muhiti ancha yaxshi.","ru":"В этом жилом комплексе довольно хорошая обстановка.","tj":"Муҳити ин маҷмааи истиқоматӣ хеле хуб аст."},"source":"course"},"小学":{"zh":"还有了一个小学生。","p":"Hái yǒule yí ge xiǎoxuéshēng.","m":{"uz":"Yana bitta boshlang‘ich maktab o‘quvchisi ham bo‘ladi.","ru":"И ещё ученик начальной школы.","tj":"Боз як хонандаи мактаби ибтидоӣ ҳам мешавад."},"source":"course"},"小学生":{"zh":"还有了一个小学生。","p":"Hái yǒule yí ge xiǎoxuéshēng.","m":{"uz":"Yana bitta boshlang‘ich maktab o‘quvchisi ham bo‘ladi.","ru":"И ещё ученик начальной школы.","tj":"Боз як хонандаи мактаби ибтидоӣ ҳам мешавад."},"source":"course"},"小孩儿":{"zh":"对，我也帮他们家的小孩儿学中文。","p":"Duì, wǒ yě bāng tāmen jiā de xiǎoháir xué Zhōngwén.","m":{"uz":"Ha, men ham ularning bolasiga xitoy tilini o‘rganishda yordam beraman.","ru":"Да, а я помогаю их ребёнку учить китайский.","tj":"Ҳа, ман ҳам ба кӯдаки онҳо дар омӯхтани чинӣ кӯмак мекунам."},"source":"course"},"小时候":{"zh":"女儿变化不小，她小时候喜欢短头发，像男孩子一样。","p":"Nǚ'ér biànhuà bù xiǎo, tā xiǎo shíhou xǐhuan duǎn tóufa, xiàng nán háizi yíyàng.","m":{"uz":"Qizimiz ancha o'zgardi, kichkinaligida kalta sochni yoqtirardi, xuddi o'g'il boladek edi.","ru":"Дочь сильно изменилась. В детстве она любила короткие волосы, была как мальчик.","tj":"Духтарамон хеле тағйир ёфтааст, хурдсолӣ мӯи кӯтоҳро дӯст медошт, мисли писарбача буд."},"source":"course"},"小朋友":{"zh":"他今天要和小朋友玩。","p":"Tā jīntiān yào hé xiǎopéngyou wán.","m":{"uz":"U bugun bolalar bilan o‘ynamoqchi.","ru":"Сегодня он хочет играть с детьми.","tj":"Ӯ имрӯз мехоҳад бо кӯдакон бозӣ кунад."},"source":"course"},"尝":{"zh":"好，那我先买几个尝尝。","p":"Hǎo, nà wǒ xiān mǎi jǐ ge chángchang.","m":{"uz":"Yaxshi, unda avval bir nechtasini olib tatib ko'raman.","ru":"Хорошо, тогда сначала куплю несколько попробовать.","tj":"Хуб, пас аввал чандто мехарам, бичашам."},"source":"course"},"屋子":{"zh":"屋子里有一张桌子。","p":"Wūzi lǐ yǒu yì zhāng zhuōzi.","m":{"uz":"Xonada bitta stol bor.","ru":"В комнате стоит один стол.","tj":"Дар хона як миз ҳаст."},"source":"authored"},"山":{"zh":"我觉得爬山累得很。","p":"Wǒ juéde páshān lèi de hěn.","m":{"uz":"Menimcha, tog‘ga chiqish juda charchatadi.","ru":"Мне кажется, подниматься в горы очень утомительно.","tj":"Ба назарам, кӯҳ баромадан хеле хаста мекунад."},"source":"course"},"工作日":{"zh":"去吧！今天是工作日，人应该不多。","p":"Qù ba! Jīntiān shì gōngzuòrì, rén yīnggāi bù duō.","m":{"uz":"Bor! Bugun ish kuni, odam ko‘p bo‘lmasligi kerak.","ru":"Иди! Сегодня рабочий день, людей должно быть немного.","tj":"Рав! Имрӯз рӯзи корӣ аст, одам набояд зиёд бошад."},"source":"course"},"左":{"zh":"我喜欢左边这个。","p":"Wǒ xǐhuan zuǒbian zhège.","m":{"uz":"Menga chapdagisi yoqdi.","ru":"Мне нравится тот, что слева.","tj":"Ба ман тарафи чап писанд аст."},"source":"course"},"差不多":{"zh":"差不多一半儿吧。","p":"Chàbuduō yíbànr ba.","m":{"uz":"Taxminan yarmi bo'lsa kerak.","ru":"Наверное, примерно половина.","tj":"Тақрибан нисфаш бошад."},"source":"course"},"常":{"zh":"非常喜欢。","p":"Fēicháng xǐhuan.","m":{"uz":"Juda yaxshi ko'raman.","ru":"Очень нравится.","tj":"Хеле дӯст медорам."},"source":"course"},"常常":{"zh":"她对每个人都笑，也常常对我笑。","p":"Tā duì měi ge rén dōu xiào, yě chángcháng duì wǒ xiào.","m":{"uz":"U hammaga kulib qaraydi, menga ham tez-tez kuladi.","ru":"Она улыбается каждому и часто улыбается мне.","tj":"Вай ба ҳар кас механдад, ба ман ҳам зуд-зуд механдад."},"source":"course"},"常用":{"zh":"有，这些常用的东西我都放在包里了，我给你拿。","p":"Yǒu, zhèxiē chángyòng de dōngxi wǒ dōu fàng zài bāo lǐ le, wǒ gěi nǐ ná.","m":{"uz":"Bor, tez-tez kerak bo‘ladigan narsalarning hammasini sumkamga solganman, olib beraman.","ru":"Есть. Все такие нужные вещи я держу в сумке, сейчас достану.","tj":"Ҳаст. Ҳамаи ин чизҳои лозимиро дар халта мондаам, ҳозир медиҳам."},"source":"course"},"常见":{"zh":"你想多了，做错事情是很常见的。","p":"Nǐ xiǎng duō le, zuò cuò shìqing shì hěn chángjiàn de.","m":{"uz":"Ortiqcha o‘ylayapsan, xato qilish juda odatiy hol.","ru":"Ты слишком переживаешь, ошибаться — обычное дело.","tj":"Аз ҳад зиёд фикр мекунӣ, хато кардан кори маъмул аст."},"source":"course"},"干":{"zh":"把苹果洗干净了！","p":"Bǎ píngguǒ xǐ gānjìng le!","m":{"uz":"Olmani yaxshilab yuvib!","ru":"Тщательно помой яблоки!","tj":"Себро хуб бишӯй!"},"source":"course"},"平时":{"zh":"平时孩子们在哪儿玩？","p":"Píngshí háizimen zài nǎr wán?","m":{"uz":"Odatda bolalar qayerda o‘ynaydi?","ru":"Где дети обычно играют?","tj":"Одатан кӯдакон дар куҷо бозӣ мекунанд?"},"source":"course"},"床":{"zh":"你每天几点起床？","p":"Nǐ měitiān jǐ diǎn qǐchuáng?","m":{"uz":"Sen har kuni soat nechada turasan?","ru":"В котором часу ты каждый день встаёшь?","tj":"Ту ҳар рӯз соати чанд аз хоб мехезӣ?"},"source":"course"},"店":{"zh":"我去商店了。","p":"Wǒ qù shāngdiàn le.","m":{"uz":"Men do'konga bordim.","ru":"Я ходил в магазин.","tj":"Ман ба дӯкон рафтам."},"source":"course"},"开会":{"zh":"那什么时候开会？","p":"Nà shénme shíhou kāihuì?","m":{"uz":"Unda yig‘ilish qachon bo‘ladi?","ru":"Тогда когда будет совещание?","tj":"Пас ҷаласа кай мешавад?"},"source":"course"},"开学":{"zh":"开学已经三个多星期了。","p":"Kāixué yǐjīng sān ge duō xīngqī le.","m":{"uz":"O‘qish boshlanganiga uch haftadan oshdi.","ru":"С начала учёбы прошло уже больше трёх недель.","tj":"Аз оғози таҳсил зиёда аз се ҳафта гузашт."},"source":"course"},"开机":{"zh":"已经接好了，您开机看看有没有问题。","p":"Yǐjīng jiē hǎo le, nín kāijī kànkan yǒu méiyǒu wèntí.","m":{"uz":"Ha, ulandi. Yoqib ko‘ring, muammo bormi yo‘qmi.","ru":"Да, уже подключён. Включите и проверьте, всё ли работает.","tj":"Ҳа, пайваст шуд. Фурӯзон карда бинед, мушкил ҳаст ё не."},"source":"course"},"开花":{"zh":"王老师，您看，这条街上的树都开花了。","p":"Wáng lǎoshī, nín kàn, zhè tiáo jiē shàng de shù dōu kāihuā le.","m":{"uz":"Ustoz Wang, qarang, bu ko‘chadagi daraxtlarning hammasi gullabdi.","ru":"Учитель Ван, смотрите, деревья на этой улице уже цветут.","tj":"Устод Ван, бинед, дарахтони ин кӯча ҳама гул кардаанд."},"source":"course"},"开车":{"zh":"我没开车，坐车呢。","p":"Wǒ méi kāichē, zuò chē ne.","m":{"uz":"Mashina haydamayapman, transportda ketyapman.","ru":"Нет, я не за рулём, еду на машине.","tj":"Не, мошин намеронам, бо нақлиёт меравам."},"source":"course"},"得分":{"zh":"在比赛中，他得分最高。","p":"Zài bǐsài zhōng, tā défēn zuì gāo.","m":{"uz":"Musobaqada u eng ko‘p ochko oldi.","ru":"В соревновании он набрал больше всех очков.","tj":"Дар мусобиқа ӯ аз ҳама бештар хол гирифт."},"source":"course"},"得到":{"zh":"眼镜找不到了，你帮我找得到吗？","p":"Yǎnjìng zhǎo bu dào le, nǐ bāng wǒ zhǎo de dào ma?","m":{"uz":"Ko'zoynak topilmayapti, siz topib bera olasizmi?","ru":"Очки не нахожу — ты можешь помочь найти?","tj":"Айнак ёфта намешавад, оё шумо ёрӣ расонда ёфта метавонед?"},"source":"course"},"心里":{"zh":"她心里很高兴。","p":"Tā xīnlǐ hěn gāoxìng.","m":{"uz":"Uning ko‘ngli juda xursand.","ru":"Она очень рада.","tj":"Ӯ дар дилаш хеле хурсанд аст."},"source":"authored"},"忘":{"zh":"难过的事情不一会儿就忘了。","p":"Nánguò de shìqing bù yíhuìr jiù wàng le.","m":{"uz":"Xafa qilgan voqeani ko‘p o‘tmay unutib yubordim.","ru":"Грустное событие вскоре забылось.","tj":"Ҳодисаи ғамангез дере нагузашта фаромӯш шуд."},"source":"course"},"快要":{"zh":"快要下雨了，带上伞吧。","p":"Kuài yào xiàyǔ le, dài shàng sǎn ba.","m":{"uz":"Tez orada yomg'ir yog'adi, soyabon oling.","ru":"Скоро пойдёт дождь, возьмите зонт.","tj":"Зуд борон мешавад, чатр гиред."},"source":"course"},"怎么办":{"zh":"你看，我这么胖，怎么办呢？","p":"Nǐ kàn, wǒ zhème pàng, zěnme bàn ne?","m":{"uz":"Qara, men shuncha semizman, nima qilaman?","ru":"Смотри, я такая полная, что мне делать?","tj":"Бубин, ман ин қадар фарбеҳам, чӣ кор кунам?"},"source":"course"},"怎样":{"zh":"你们怎样过节？","p":"Nǐmen zěnyàng guòjié?","m":{"uz":"Sizlar bayramni qanday nishonlaysizlar?","ru":"Как вы отмечаете праздник?","tj":"Шумо идро чӣ тавр ҷашн мегиред?"},"source":"course"},"怕":{"zh":"我有点儿害怕。","p":"Wǒ yǒudiǎnr hàipà.","m":{"uz":"Biroz qo'rqyapman.","ru":"Мне немного страшно.","tj":"Каме метарсам."},"source":"course"},"急":{"zh":"慢慢走，别着急！","p":"Mànmàn zǒu, bié zháojí!","m":{"uz":"Sekin-sekin yuring, shoshilmang!","ru":"Идите медленно, не торопитесь!","tj":"Оҳиста-оҳиста равед, шитоб накунед!"},"source":"course"},"总":{"zh":"她总是笑着跟客人说话。","p":"Tā zǒngshì xiào zhe gēn kèrén shuōhuà.","m":{"uz":"U doim kulib mehmonlar bilan gaplashadi.","ru":"Она всегда разговаривает с покупателями с улыбкой.","tj":"Вай ҳамеша бо табассум бо харидорон сӯҳбат мекунад."},"source":"course"},"感到":{"zh":"听到这个消息，我感到很高兴。","p":"Tīngdào zhège xiāoxi, wǒ gǎndào hěn gāoxìng.","m":{"uz":"Bu xabarni eshitib, juda xursand bo‘ldim.","ru":"Услышав эту новость, я очень обрадовался.","tj":"Ин хабарро шунида, хеле хурсанд шудам."},"source":"authored"},"懂得":{"zh":"他懂得尊重别人。","p":"Tā dǒngde zūnzhòng biérén.","m":{"uz":"U boshqalarni hurmat qilishni biladi.","ru":"Он умеет уважать других.","tj":"Ӯ эҳтиром кардани дигаронро медонад."},"source":"authored"},"或":{"zh":"可以坐缆车或者走路上去。","p":"Kěyǐ zuò lǎnchē huòzhě zǒulù shàngqù.","m":{"uz":"Kanatli aravacha bilan yoki piyoda chiqish mumkin.","ru":"Можно подняться на фуникулёре или пешком.","tj":"Метавонед бо канаткаш ё пиёда боло равед."},"source":"course"},"房子":{"zh":"听说你最近打算买房子？","p":"Tīngshuō nǐ zuìjìn dǎsuàn mǎi fángzi?","m":{"uz":"Eshitishimcha, oxirgi paytda uy olmoqchisan?","ru":"Слышал, ты в последнее время собираешься купить квартиру?","tj":"Шунидам, ки вақтҳои охир хона хариданӣ ҳастӣ?"},"source":"course"},"才":{"zh":"你怎么才来？","p":"Nǐ zěnme cái lái?","m":{"uz":"Nega endi kelding?","ru":"Почему ты только сейчас пришёл?","tj":"Чаро танҳо ҳоло омадӣ?"},"source":"course"},"打":{"zh":"好打车。","p":"Hǎo dǎchē.","m":{"uz":"Taksi tutish oson.","ru":"Легко.","tj":"Осон аст."},"source":"course"},"打开":{"zh":"谢谢您，我可以打开吗？","p":"Xièxie nín, wǒ kěyǐ dǎkāi ma?","m":{"uz":"Rahmat, ochsam bo‘ladimi?","ru":"Спасибо, можно открыть?","tj":"Раҳмат, кушоям мешавад?"},"source":"course"},"打车":{"zh":"好打车。","p":"Hǎo dǎchē.","m":{"uz":"Taksi tutish oson.","ru":"Легко.","tj":"Осон аст."},"source":"course"},"拍照":{"zh":"我想出去拍照，但是天天下雨。","p":"Wǒ xiǎng chūqù pāizhào, dànshì tiāntiān xiàyǔ.","m":{"uz":"Suratga olish uchun tashqariga chiqmoqchiman, lekin har kuni yomg‘ir yog‘yapti.","ru":"Хочу выйти пофотографировать, но каждый день идёт дождь.","tj":"Мехоҳам барои аксбардорӣ берун равам, аммо ҳар рӯз борон меборад."},"source":"course"},"挺":{"zh":"这个小区环境挺好的。","p":"Zhège xiǎoqū huánjìng tǐng hǎo de.","m":{"uz":"Bu turar-joy majmuasining muhiti ancha yaxshi.","ru":"В этом жилом комплексе довольно хорошая обстановка.","tj":"Муҳити ин маҷмааи истиқоматӣ хеле хуб аст."},"source":"course"},"搬家":{"zh":"星期天我们真的能搬家吗？","p":"Xīngqītiān wǒmen zhēn de néng bānjiā ma?","m":{"uz":"Yakshanba kuni rostdan ham ko‘cha olamizmi?","ru":"Мы правда сможем переехать в воскресенье?","tj":"Рӯзи якшанбе воқеан кӯчида метавонем?"},"source":"course"},"收":{"zh":"另外，收入也不错。","p":"Lìngwài, shōurù yě búcuò.","m":{"uz":"Bundan tashqari, daromadi ham yaxshi.","ru":"Кроме того, доход тоже неплохой.","tj":"Ғайр аз ин, даромад ҳам хуб аст."},"source":"course"},"收到":{"zh":"我昨天收到了你的信。","p":"Wǒ zuótiān shōudào le nǐ de xìn.","m":{"uz":"Kecha xatingni oldim.","ru":"Вчера я получил твоё письмо.","tj":"Ман дирӯз номаи туро гирифтам."},"source":"authored"},"放假":{"zh":"学校下周开始放假。","p":"Xuéxiào xià zhōu kāishǐ fàngjià.","m":{"uz":"Maktabda kelasi haftadan ta’til boshlanadi.","ru":"В школе каникулы начнутся на следующей неделе.","tj":"Дар мактаб таътил аз ҳафтаи оянда сар мешавад."},"source":"authored"},"放学":{"zh":"放学后我们一起回家。","p":"Fàngxué hòu wǒmen yìqǐ huíjiā.","m":{"uz":"Darsdan keyin birga uyga qaytamiz.","ru":"После занятий мы вместе пойдём домой.","tj":"Баъди дарс якҷоя ба хона меравем."},"source":"authored"},"斤":{"zh":"三块五一斤。","p":"Sān kuài wǔ yì jīn.","m":{"uz":"Bir jin uchun uch yuan besh fen.","ru":"Три юаня пятьдесят за полкило.","tj":"Барои як ҷин се юан панҷ феник."},"source":"course"},"方便面":{"zh":"晚上我吃了一碗方便面。","p":"Wǎnshang wǒ chī le yì wǎn fāngbiànmiàn.","m":{"uz":"Kechqurun bir kosa tez tayyor bo‘ladigan ugra yedim.","ru":"Вечером я съел тарелку лапши быстрого приготовления.","tj":"Бегоҳ як коса угрои тезтайёр хӯрдам."},"source":"authored"},"方向":{"zh":"请往这个方向走。","p":"Qǐng wǎng zhège fāngxiàng zǒu.","m":{"uz":"Iltimos, shu tomonga yuring.","ru":"Пожалуйста, идите в эту сторону.","tj":"Лутфан, ба ҳамин самт равед."},"source":"authored"},"方法":{"zh":"没有什么特别的方法，认真听课，认真记笔记。","p":"Méiyǒu shénme tèbié de fāngfǎ, rènzhēn tīngkè, rènzhēn jì bǐjì.","m":{"uz":"Maxsus usul yo‘q: darsni diqqat bilan tinglayman va konspektni puxta yozaman.","ru":"Ничего особенного: внимательно слушаю урок и тщательно веду конспект.","tj":"Усули махсус нест: дарсро бодиққат мешунавам ва қайдҳоро ҷиддӣ менависам."},"source":"course"},"早饭":{"zh":"我吃了早饭就去学校了。","p":"Wǒ chī le zǎofàn jiù qù xuéxiào le.","m":{"uz":"Nonushta qilganimdan keyin darhol maktabga ketdim.","ru":"После завтрака я сразу пошёл в школу.","tj":"Баъди наҳорӣ фавран ба мактаб рафтам."},"source":"course"},"时":{"zh":"九个小时。","p":"Jiǔ ge xiǎoshí.","m":{"uz":"To‘qqiz soat.","ru":"Девять часов.","tj":"Нӯҳ соат."},"source":"course"},"明年":{"zh":"明年女儿上中学。","p":"Míngnián nǚ'ér shàng zhōngxué.","m":{"uz":"Kelasi yil qizimiz o‘rta maktabga boradi.","ru":"В следующем году дочь пойдёт в среднюю школу.","tj":"Соли оянда духтарамон ба мактаби миёна меравад."},"source":"course"},"星期天":{"zh":"放心吧。星期天六点半见！","p":"Fàngxīn ba. Xīngqītiān liù diǎn bàn jiàn!","m":{"uz":"Xotirjam bo'l. Yakshanba olti yarimda ko'rishamiz!","ru":"Не волнуйся. Увидимся в воскресенье в половине седьмого!","tj":"Хавотир нашав. Якшанбе соати шашу ним мебинем!"},"source":"course"},"星期日":{"zh":"今天星期日。","p":"Jīntiān Xīngqīrì.","m":{"uz":"Bugun yakshanba.","ru":"Сегодня воскресенье.","tj":"Имрӯз якшанбе аст."},"source":"course"},"春天":{"zh":"当然是春天，天气不那么冷了，草和树都绿了，花也开了。","p":"Dāngrán shì chūntiān, tiānqì bù nàme lěng le, cǎo hé shù dōu lǜ le, huā yě kāi le.","m":{"uz":"Albatta bahor, havo endi unchalik sovuq emas, o'tlar va daraxtlar yashillandi, gullar ham ochildi.","ru":"Конечно весну: погода уже не такая холодная, трава и деревья стали зелёными, цветы тоже раскрылись.","tj":"Албатта баҳорро: ҳаво дигар он қадар сард нест, алафу дарахтон сабз шуданд, гулҳо ҳам кушоданд."},"source":"course"},"春节":{"zh":"春节大概放七八天假。","p":"Chūnjié dàgài fàng qī bā tiān jià.","m":{"uz":"Bahor bayramida taxminan yetti-sakkiz kun ta’til bo‘ladi.","ru":"На Праздник Весны обычно дают примерно семь-восемь дней выходных.","tj":"Дар Иди Баҳор тақрибан ҳафт-ҳашт рӯз таътил мешавад."},"source":"course"},"晚":{"zh":"小雪今天来晚了。","p":"Xiǎoxuě jīntiān láiwǎn le.","m":{"uz":"Xiaoxue bugun kech keldi.","ru":"Сяосюэ сегодня пришла поздно.","tj":"Сяосюэ имрӯз дер омад."},"source":"course"},"晚会":{"zh":"下周学校有晚会，你知道吗？","p":"Xià zhōu xuéxiào yǒu wǎnhuì, nǐ zhīdào ma?","m":{"uz":"Keyingi hafta maktabda kecha bo‘ladi, bilasanmi?","ru":"На следующей неделе в школе будет вечер, знаешь?","tj":"Ҳафтаи оянда дар мактаб шомгоҳӣ мешавад, медонӣ?"},"source":"course"},"晚点":{"zh":"您好！不好意思，飞机晚点了，让您久等了。","p":"Nín hǎo! Bù hǎoyìsi, fēijī wǎndiǎn le, ràng nín jiǔ děng le.","m":{"uz":"Salom! Uzr, samolyot kechikdi, sizni uzoq kuttirib qo‘ydik.","ru":"Здравствуйте! Простите, самолёт задержался, вам пришлось долго ждать.","tj":"Салом! Бубахшед, ҳавопаймо дер кард ва шуморо зиёд интизор кардем."},"source":"course"},"晚饭":{"zh":"星期天我们去哪儿吃晚饭？","p":"Xīngqītiān wǒmen qù nǎr chī wǎnfàn?","m":{"uz":"Yakshanba kuni kechki ovqatni qayerda yeymiz?","ru":"Куда мы пойдём ужинать в воскресенье?","tj":"Рӯзи якшанбе барои шом ба куҷо меравем?"},"source":"course"},"景点":{"zh":"这个景点每天有很多游客。","p":"Zhège jǐngdiǎn měitiān yǒu hěn duō yóukè.","m":{"uz":"Bu diqqatga sazovor joyga har kuni ko‘p sayyoh keladi.","ru":"В это место каждый день приезжает много туристов.","tj":"Ҳар рӯз ба ин макони тамошобоб сайёҳони зиёд меоянд."},"source":"authored"},"最好":{"zh":"九月去北京旅游最好。","p":"Jiǔ yuè qù Běijīng lǚyóu zuì hǎo.","m":{"uz":"Sent'abrda Pekinga sayohat qilish eng yaxshi.","ru":"Лучше всего ехать в Пекин в сентябре.","tj":"Дар моҳи сентябр сафар ба Пекин аз ҳама беҳтар аст."},"source":"course"},"有些":{"zh":"有些人喜欢喝茶。","p":"Yǒuxiē rén xǐhuan hē chá.","m":{"uz":"Ba’zi odamlar choy ichishni yoqtiradi.","ru":"Некоторые люди любят пить чай.","tj":"Баъзе одамон чой нӯшиданро дӯст медоранд."},"source":"authored"},"有关":{"zh":"女孩子对衣服颜色的选择往往与她们的性格有关。","p":"Nǚháizi duì yīfu yánsè de xuǎnzé wǎngwǎng yǔ tāmen de xìnggé yǒuguān.","m":{"uz":"Qizlarning kiyim rangi tanlovi ko'pincha ularning xarakteri bilan bog'liq.","ru":"Выбор цвета одежды у девушек часто связан с их характером.","tj":"Интихоби ранги либос дар духтарон аксаран бо характери онҳо вобаста аст."},"source":"course"},"有时":{"zh":"还有时间，你上来吧。","p":"Hái yǒu shíjiān, nǐ shànglái ba.","m":{"uz":"Hali vaqt bor, sen yuqoriga chiq.","ru":"Время ещё есть, поднимайся ко мне.","tj":"Ҳоло вақт ҳаст, ту боло биё."},"source":"course"},"有点儿":{"zh":"我有点儿害怕。","p":"Wǒ yǒudiǎnr hàipà.","m":{"uz":"Biroz qo'rqyapman.","ru":"Мне немного страшно.","tj":"Каме метарсам."},"source":"course"},"有用":{"zh":"我给你介绍几个有用的网站。","p":"Wǒ gěi nǐ jièshào jǐ ge yǒuyòng de wǎngzhàn.","m":{"uz":"Senga bir nechta foydali saytni tavsiya qilaman.","ru":"Я покажу тебе несколько полезных сайтов.","tj":"Ба ту чанд сомонаи муфидро нишон медиҳам."},"source":"course"},"有的":{"zh":"天啊！有的还不到二十块钱。","p":"Tiān a! Yǒude hái bú dào èrshí kuài qián.","m":{"uz":"Voy! Ba’zilari hatto yigirma yuanga ham yetmaydi.","ru":"Ничего себе! Некоторые стоят даже меньше двадцати юаней.","tj":"Вой! Баъзеаш ҳатто ба бист юан ҳам намерасад."},"source":"course"},"服务":{"zh":"服务员，我房间的门打不开了。","p":"Fúwùyuán, wǒ fángjiān de mén dǎ bù kāi le.","m":{"uz":"Ofitsiant, xonamning eshigi ochmayapti.","ru":"Сотрудник, дверь моего номера не открывается.","tj":"Хизматрасон, дари хонаи ман намекушояд."},"source":"course"},"服务台":{"zh":"别着急，我们拿着护照和机票，去服务台问问吧。","p":"Bié zháojí, wǒmen názhe hùzhào hé jīpiào, qù fúwùtái wènwen ba.","m":{"uz":"Xavotir olma, pasport va chiptalarimiz yonimizda, xizmat ko‘rsatish peshtaxtasiga borib so‘raylik.","ru":"Не волнуйся. Паспорт и билеты у нас с собой, пойдём спросим на стойке обслуживания.","tj":"Ташвиш накаш, шиноснома ва чиптаҳо бо мост, биё ба мизи хизматрасонӣ рафта пурсем."},"source":"course"},"本子":{"zh":"我会把这些题都记在本子上。","p":"Wǒ huì bǎ zhèxiē tí dōu jì zài běnzi shàng.","m":{"uz":"Bu savollarning hammasini daftarga yozib olaman.","ru":"Я запишу все эти задания в тетрадь.","tj":"Ман ҳамаи ин саволҳоро дар дафтар қайд мекунам."},"source":"course"},"机票":{"zh":"出去玩的机票买好了吗？","p":"Chūqù wán de jīpiào mǎi hǎo le ma?","m":{"uz":"Sayohat uchun aviachiptalarni olib bo‘ldingmi?","ru":"Билеты на поездку уже куплены?","tj":"Чиптаҳои сафарро харида шуд?"},"source":"course"},"杯":{"zh":"杯子在哪儿？","p":"Bēizi zài nǎr?","m":{"uz":"Piyola qayerda?","ru":"Где стакан?","tj":"Пиёла куҷост?"},"source":"course"},"极":{"zh":"今年夏天热极了。","p":"Jīnnián xiàtiān rè jí le.","m":{"uz":"Bu yoz nihoyatda issiq.","ru":"Этим летом ужасно жарко.","tj":"Имсол тобистон ниҳоят гарм аст."},"source":"course"},"查":{"zh":"好，那我上网查一查。","p":"Hǎo, nà wǒ shàngwǎng chá yì chá.","m":{"uz":"Xo‘p, unda internetdan tekshirib ko‘raman.","ru":"Хорошо, тогда посмотрю информацию в интернете.","tj":"Хуб, пас аз интернет маълумот меҷӯям."},"source":"course"},"校园":{"zh":"家月，对不起，我昨天忘了还你校园卡了。","p":"Jiāyuè, duìbuqǐ, wǒ zuótiān wàng le huán nǐ xiàoyuánkǎ le.","m":{"uz":"Jiayue, uzr, kecha kampus kartangni qaytarishni unutibman.","ru":"Цзяюэ, прости, я вчера забыл вернуть твою кампус-карту.","tj":"Ҷяюэ, бубахш, дирӯз корти кампусатро баргардонданро фаромӯш кардам."},"source":"course"},"检票":{"zh":"去哪里检票？","p":"Qù nǎlǐ jiǎnpiào?","m":{"uz":"Chipta qayerda tekshiriladi?","ru":"Где проходить проверку билетов?","tj":"Чиптаро дар куҷо месанҷанд?"},"source":"course"},"楼梯":{"zh":"你进去吧，我在楼梯那儿等你。我害怕见李老师。","p":"Nǐ jìnqu ba, wǒ zài lóutī nàr děng nǐ. Wǒ hàipà jiàn Lǐ lǎoshī.","m":{"uz":"Sen kiraver, men zina yonida kutaman. Ustoz Lini ko‘rishdan qo‘rqyapman.","ru":"Ты заходи, я подожду у лестницы. Я боюсь встречаться с учителем Ли.","tj":"Ту даро, ман назди зинапоя интизор мешавам. Аз дидани устод Ли метарсам."},"source":"course"},"歌":{"zh":"你唱歌很好听。","p":"Nǐ chànggē hěn hǎotīng.","m":{"uz":"Sen juda chiroyli kuylaysan.","ru":"Ты очень хорошо поёшь.","tj":"Ту хеле хуш месароӣ."},"source":"course"},"正":{"zh":"正在准备午饭呢！","p":"Zhèngzài zhǔnbèi wǔfàn ne!","m":{"uz":"Hozir tushlikni tayyorlayapti!","ru":"Сейчас готовит обед!","tj":"Ҳоло нисфирӯзиро тайёр мекунад!"},"source":"course"},"比如":{"zh":"比如一块橡皮、一块糖，得到了就很幸福。","p":"Bǐrú yí kuài xiàngpí, yí kuài táng, dédào le jiù hěn xìngfú.","m":{"uz":"Masalan, bir dona o'chirg'ich yoki konfetni olsang, juda baxtli bo'lasan.","ru":"Например, получишь ластик или конфету - и уже счастлив.","tj":"Масалан, як хатпоккунак ё як қанд гирӣ, хеле хушбахт мешавӣ."},"source":"course"},"毕业":{"zh":"我一毕业就去上海当律师了。","p":"Wǒ yì bìyè jiù qù Shànghǎi dāng lǜshī le.","m":{"uz":"Bitirishim bilan Shanghaiga advokat bo'lib ishlashga ketdim.","ru":"Сразу после выпуска я поехала в Шанхай работать юристом.","tj":"Ҳамин ки хатм кардам, ба Шанхай рафта адвокат шудам."},"source":"course"},"毛":{"zh":"一共五十八块五毛。","p":"Yígòng wǔshíbā kuài wǔ máo.","m":{"uz":"Jami 58 yuan 5 mao.","ru":"Всего 58 юаней 5 мао.","tj":"Ҳамагӣ 58 юану 5 мао."},"source":"course"},"沙发":{"zh":"谢谢，我想买沙发。","p":"Xièxie, wǒ xiǎng mǎi shāfā.","m":{"uz":"Rahmat, men divan olmoqchiman.","ru":"Спасибо, я хочу купить диван.","tj":"Ташаккур, ман диван харидан мехоҳам."},"source":"course"},"没":{"zh":"我没买。","p":"Wǒ méi mǎi.","m":{"uz":"Men hech narsa sotib olmadim.","ru":"Я ничего не купил.","tj":"Ман ҳеҷ чиз нахаридам."},"source":"course"},"没事":{"zh":"没事，我只喝一杯。","p":"Méi shì, wǒ zhǐ hē yì bēi.","m":{"uz":"Hechqisi yo'q, faqat bir piyola ichaman.","ru":"Ничего, я выпью только одну чашку.","tj":"Ҳеҷ гап не, танҳо як пиёла менӯшам."},"source":"course"},"没意思":{"zh":"这部电影没意思。","p":"Zhè bù diànyǐng méi yìsi.","m":{"uz":"Bu film zerikarli.","ru":"Этот фильм скучный.","tj":"Ин филм дилгиркунанда аст."},"source":"authored"},"河":{"zh":"我知道，是黄河！","p":"Wǒ zhīdào, shì Huáng Hé!","m":{"uz":"Bilaman, bu Sariq daryo!","ru":"Знаю — Хуанхэ!","tj":"Медонам, Хуанхэ!"},"source":"course"},"洗衣机":{"zh":"洗衣机也坏了吗？","p":"Xǐyījī yě huài le ma?","m":{"uz":"Kir yuvish mashinasi ham buzildimi?","ru":"Стиральная машина тоже сломалась?","tj":"Мошини ҷомашӯӣ ҳам вайрон шуд?"},"source":"course"},"海":{"zh":"现在去海边有点儿冷。","p":"Xiànzài qù hǎibiān yǒudiǎnr lěng.","m":{"uz":"Hozir dengiz bo‘yiga borish biroz sovuq.","ru":"Сейчас на море немного холодно.","tj":"Ҳоло ба соҳил рафтан каме хунук аст."},"source":"course"},"游":{"zh":"你经常游泳吗？","p":"Nǐ jīngcháng yóuyǒng ma?","m":{"uz":"Sen tez-tez suzasanmi?","ru":"Ты часто плаваешь?","tj":"Оё ту зуд-зуд шино мекунӣ?"},"source":"course"},"游客":{"zh":"这个景点每天有很多游客。","p":"Zhège jǐngdiǎn měitiān yǒu hěn duō yóukè.","m":{"uz":"Bu diqqatga sazovor joyga har kuni ko‘p sayyoh keladi.","ru":"В это место каждый день приезжает много туристов.","tj":"Ҳар рӯз ба ин макони тамошобоб сайёҳони зиёд меоянд."},"source":"authored"},"火车":{"zh":"你们上火车后看见王老师了吗？","p":"Nǐmen shàng huǒchē hòu kànjiàn Wáng lǎoshī le ma?","m":{"uz":"Poyezdga chiqqaningizdan keyin ustoz Wangni ko‘rdingizmi?","ru":"После посадки в поезд вы видели преподавателя Ван?","tj":"Баъди савор шудан ба қатор устод Ванро дидед?"},"source":"course"},"照":{"zh":"我照顾啊。","p":"Wǒ zhàogu a.","m":{"uz":"Men qarayman-da.","ru":"Я буду ухаживать.","tj":"Ман нигоҳубин мекунам."},"source":"course"},"照相":{"zh":"我的照相机被谁拿走了？怎么找不到了？","p":"Wǒ de zhàoxiàngjī bèi shéi ná zǒu le? Zěnme zhǎo bu dào le?","m":{"uz":"Fotoapparatimni kim olib ketdi? Nega topa olmayapman?","ru":"Кто забрал мой фотоаппарат? Почему я не могу его найти?","tj":"Фотоаппарати маро кӣ гирифта рафт? Чаро ёфта наметавонам?"},"source":"course"},"爬":{"zh":"我觉得爬山累得很。","p":"Wǒ juéde páshān lèi de hěn.","m":{"uz":"Menimcha, tog‘ga chiqish juda charchatadi.","ru":"Мне кажется, подниматься в горы очень утомительно.","tj":"Ба назарам, кӯҳ баромадан хеле хаста мекунад."},"source":"course"},"爱情片":{"zh":"我记得你喜欢看爱情片，我们看那个爱情片，怎么样？","p":"Wǒ jìde nǐ xǐhuan kàn àiqíngpiàn, wǒmen kàn nàge àiqíngpiàn, zěnmeyàng?","m":{"uz":"Esimda, sen romantik filmlarni yoqtirasan. O‘sha romantik filmni ko‘rsak qanday?","ru":"Я помню, ты любишь романтические фильмы. Как насчёт того?","tj":"Дар хотир дорам, ту филмҳои ошиқонаро дӯст медорӣ. Он филмро бинем, чӣ хел?"},"source":"course"},"牛":{"zh":"好吧，牛奶呢？","p":"Hǎo ba, niúnǎi ne?","m":{"uz":"Mayli, sut qani?","ru":"Ладно, а где молоко?","tj":"Хуб, шир куҷост?"},"source":"course"},"玩":{"zh":"他今天要和小朋友玩。","p":"Tā jīntiān yào hé xiǎopéngyou wán.","m":{"uz":"U bugun bolalar bilan o‘ynamoqchi.","ru":"Сегодня он хочет играть с детьми.","tj":"Ӯ имрӯз мехоҳад бо кӯдакон бозӣ кунад."},"source":"course"},"班级":{"zh":"我们班级有二十个学生。","p":"Wǒmen bānjí yǒu èrshí ge xuésheng.","m":{"uz":"Sinfimizda yigirma nafar o‘quvchi bor.","ru":"В нашем классе двадцать учеников.","tj":"Дар синфи мо бист хонанда ҳаст."},"source":"authored"},"球":{"zh":"今天去不去打球？","p":"Jīntiān qù bú qù dǎ qiú?","m":{"uz":"Bugun to'p o'ynagani borami?","ru":"Сегодня идёшь играть в мяч?","tj":"Имрӯз ба бозии тӯб меравӣ?"},"source":"course"},"球场":{"zh":"我正在球场打球呢，接了你的电话就跑过来了。","p":"Wǒ zhèngzài qiúchǎng dǎqiú ne, jiē le nǐ de diànhuà jiù pǎo guòlái le.","m":{"uz":"Men sport maydonida to‘p o‘ynayotgan edim, qo‘ng‘irog‘ingni olib darrov yugurib keldim.","ru":"Я играл на площадке; как только ответил на твой звонок, сразу прибежал.","tj":"Ман дар майдон тӯб бозӣ мекардам, зангатро гирифтаму фавран давида омадам."},"source":"course"},"电":{"zh":"电脑接好了吗？","p":"Diànnǎo jiē hǎo le ma?","m":{"uz":"Kompyuter ulandimi?","ru":"Компьютер подключён?","tj":"Компютер пайваст шуд?"},"source":"course"},"电子书":{"zh":"进不去图书馆也没关系，上网看看有没有电子书。","p":"Jìn bu qù túshūguǎn yě méi guānxi, shàngwǎng kànkan yǒu méiyǒu diànzǐshū.","m":{"uz":"Kutubxonaga kira olmasang ham hechqisi yo‘q, internetdan elektron kitob bor-yo‘qligini ko‘r.","ru":"Ничего страшного, если не войдёшь в библиотеку; посмотри электронную книгу в интернете.","tj":"Агар ба китобхона даромада натавонӣ ҳам, ҳеҷ гап нест, аз интернет китоби электронӣ ҳаст ё не бин."},"source":"course"},"电影院":{"zh":"是啊，电影院还不小。","p":"Shì a, diànyǐngyuàn hái bù xiǎo.","m":{"uz":"Ha, kinoteatr ham kichik emas.","ru":"Да, и кинотеатр немаленький.","tj":"Ҳа, кинотеатр ҳам хурд нест."},"source":"course"},"电话":{"zh":"电话是谁打的？","p":"Diànhuà shì shéi dǎ de?","m":{"uz":"Telefon kimdan edi?","ru":"Кто звонил?","tj":"Занг аз кӣ буд?"},"source":"course"},"男孩儿":{"zh":"旁边那个男孩儿就穿了这样的裤子，我觉得很好看啊！","p":"Pángbian nàge nánháir jiù chuānle zhèyàng de kùzi, wǒ juéde hěn hǎokàn a!","m":{"uz":"Yonimizdagi bola ham shunday shim kiygan, menimcha juda chiroyli!","ru":"Вон мальчик рядом носит такие брюки, по-моему, выглядят отлично!","tj":"Писарбачаи паҳлӯ ҳамин хел шим пӯшидааст, ба назарам хеле зебост!"},"source":"course"},"男朋友":{"zh":"她不是有男朋友了吗？","p":"Tā bú shì yǒu nánpéngyou le ma?","m":{"uz":"Uning yigit do'sti bor-ku?","ru":"У неё же был парень?","tj":"Магар ӯ дӯстписар надошт?"},"source":"course"},"男生":{"zh":"听说为了准备运动会，你们几个男生每天都练球。","p":"Tīngshuō wèile zhǔnbèi yùndònghuì, nǐmen jǐ ge nánshēng měitiān dōu liàn qiú.","m":{"uz":"Eshitishimcha, sport musobaqasiga tayyorlanish uchun siz yigitlar har kuni to‘p mashq qilar ekansiz.","ru":"Говорят, ради подготовки к соревнованиям вы каждый день тренируетесь.","tj":"Шунидам, барои омодагӣ ба мусобиқаҳо шумо ҳар рӯз машқи тӯб мекунед."},"source":"course"},"画家":{"zh":"这位画家喜欢画山水。","p":"Zhè wèi huàjiā xǐhuan huà shānshuǐ.","m":{"uz":"Bu rassom manzaralar chizishni yoqtiradi.","ru":"Этот художник любит писать пейзажи.","tj":"Ин рассом расмҳои манзаравиро дӯст медорад."},"source":"authored"},"画笔":{"zh":"就送画笔吧！","p":"Jiù sòng huàbǐ ba!","m":{"uz":"Unda qalamlar sovg‘a qilamiz!","ru":"Тогда подарим ей набор для рисования!","tj":"Пас қаламҳои расмкаширо тӯҳфа кунем!"},"source":"course"},"留学生":{"zh":"她是来中国的留学生。","p":"Tā shì lái Zhōngguó de liúxuéshēng.","m":{"uz":"U Xitoyga kelgan xorijlik talaba.","ru":"Она иностранная студентка, приехавшая в Китай.","tj":"Ӯ донишҷӯи хориҷиест, ки ба Чин омадааст."},"source":"authored"},"病人":{"zh":"大医院病人多，医生非常忙。","p":"Dà yīyuàn bìngrén duō, yīshēng fēicháng máng.","m":{"uz":"Katta kasalxonalarda bemorlar ko‘p, shifokorlar juda band.","ru":"В больших больницах много пациентов, и врачи очень заняты.","tj":"Дар беморхонаҳои калон беморон бисёранд ва духтурон хеле банданд."},"source":"course"},"白天":{"zh":"我白天在家里读书，晚上和朋友们一起看电影。","p":"Wǒ báitiān zài jiālǐ dú shū, wǎnshang hé péngyoumen yìqǐ kàn diànyǐng.","m":{"uz":"Kunduz uyda kitob o‘qiyman, kechqurun do‘stlarim bilan birga film ko‘raman.","ru":"Днём я буду читать дома, а вечером смотреть фильм с друзьями.","tj":"Рӯзона дар хона китоб мехонам, шом бо дӯстонам якҷо филм тамошо мекунам."},"source":"course"},"白色":{"zh":"因为我喜欢白色啊！","p":"Yīnwèi wǒ xǐhuan báisè a!","m":{"uz":"Chunki men oq rangni yoqtiraman!","ru":"Потому что мне нравится белый!","tj":"Зеро ман ранги сафедро дӯст медорам!"},"source":"course"},"的话":{"zh":"你觉得满意的话，咱们就买。","p":"Nǐ juéde mǎnyì dehuà, zánmen jiù mǎi.","m":{"uz":"Agar senga ma’qul bo‘lsa, sotib olamiz.","ru":"Если тебе нравится, тогда купим.","tj":"Агар ба ту писанд бошад, мехарем."},"source":"course"},"目标":{"zh":"我的目标是每天学十个新词。","p":"Wǒ de mùbiāo shì měitiān xué shí ge xīn cí.","m":{"uz":"Maqsadim har kuni o‘nta yangi so‘z o‘rganish.","ru":"Моя цель — каждый день учить десять новых слов.","tj":"Ҳадафи ман ҳар рӯз омӯхтани даҳ калимаи нав аст."},"source":"authored"},"直到":{"zh":"他直到晚上才回家。","p":"Tā zhídào wǎnshang cái huíjiā.","m":{"uz":"U faqat kechqurun uyga qaytdi.","ru":"Он вернулся домой только вечером.","tj":"Ӯ танҳо бегоҳ ба хона баргашт."},"source":"authored"},"相机":{"zh":"我的照相机被谁拿走了？怎么找不到了？","p":"Wǒ de zhàoxiàngjī bèi shéi ná zǒu le? Zěnme zhǎo bu dào le?","m":{"uz":"Fotoapparatimni kim olib ketdi? Nega topa olmayapman?","ru":"Кто забрал мой фотоаппарат? Почему я не могу его найти?","tj":"Фотоаппарати маро кӣ гирифта рафт? Чаро ёфта наметавонам?"},"source":"course"},"看来":{"zh":"看来没有想的那么容易。","p":"Kànlái méiyǒu xiǎng de nàme róngyì.","m":{"uz":"Ko'rinishidan, o'ylaganimdek oson emas ekan.","ru":"Похоже, это не так легко, как я думал.","tj":"Маълум мешавад, он қадар осон нест."},"source":"course"},"看病":{"zh":"对，我昨天去医院看病了。","p":"Duì, wǒ zuótiān qù yīyuàn kànbìng le.","m":{"uz":"Ha, kecha kasalxonaga shifokorga ko‘ringani bordim.","ru":"Да, вчера я ходил в больницу к врачу.","tj":"Ҳа, дирӯз ба беморхона назди духтур рафтам."},"source":"course"},"睡":{"zh":"她睡得很早。","p":"Tā shuì de hěn zǎo.","m":{"uz":"U juda erta yotadi.","ru":"Она ложится спать очень рано.","tj":"Ӯ хеле барвақт мехобад."},"source":"course"},"短裤":{"zh":"裙子480，短裤400。","p":"Qúnzi sìbǎi bāshí, duǎnkù sìbǎi.","m":{"uz":"Yubka 480, shortik 400.","ru":"Юбка — 480, шорты — 400.","tj":"Юбка 480, шорт 400."},"source":"course"},"矿泉水":{"zh":"桌子上有饮料，还有矿泉水，你想喝什么就自己拿。","p":"Zhuōzi shàng yǒu yǐnliào, hái yǒu kuàngquánshuǐ, nǐ xiǎng hē shénme jiù zìjǐ ná.","m":{"uz":"Stolda ichimliklar va mineral suv bor, nimani ichging kelsa o‘zing olaver.","ru":"На столе напитки и минеральная вода, бери сама что хочешь.","tj":"Рӯйи миз нӯшокиҳо ва оби маъданӣ ҳаст, ҳар чӣ хоҳӣ худат бигир."},"source":"course"},"秋天":{"zh":"她去年秋天出生的，刚过完一岁生日。","p":"Tā qùnián qiūtiān chūshēng de, gāng guò wán yì suì shēngrì.","m":{"uz":"U o'tgan kuzda tug'ilgan, hozirgina bir yoshini o'tkazdi.","ru":"Она родилась прошлой осенью, только что отметила первый день рождения.","tj":"Ӯ тирамоҳи гузашта таваллуд шудааст, навакак яксолагиашро гузаронд."},"source":"course"},"竹子":{"zh":"大熊猫为什么只吃竹子不吃肉？","p":"Dàxióngmāo wèishénme zhǐ chī zhúzi bù chī ròu?","m":{"uz":"Nega pandalar faqat bambuk yeydi, go‘sht yemaydi?","ru":"Почему большие панды едят только бамбук, а мясо не едят?","tj":"Чаро пандаҳо танҳо бамбук мехӯранд ва гӯшт намехӯранд?"},"source":"course"},"笔":{"zh":"就送画笔吧！","p":"Jiù sòng huàbǐ ba!","m":{"uz":"Unda qalamlar sovg‘a qilamiz!","ru":"Тогда подарим ей набор для рисования!","tj":"Пас қаламҳои расмкаширо тӯҳфа кунем!"},"source":"course"},"笔记":{"zh":"他还没把笔记本电脑接好呢。","p":"Tā hái méi bǎ bǐjìběn diànnǎo jiē hǎo ne.","m":{"uz":"U hali noutbukni to‘g‘ri ulab bo‘lmadi.","ru":"Он ещё не подключил ноутбук как следует.","tj":"Ӯ ҳоло ноутбукро дуруст пайваст накардааст."},"source":"course"},"笔记本（电脑）":{"zh":"他还没把笔记本电脑接好呢。","p":"Tā hái méi bǎ bǐjìběn diànnǎo jiē hǎo ne.","m":{"uz":"U hali noutbukni to‘g‘ri ulab bo‘lmadi.","ru":"Он ещё не подключил ноутбук как следует.","tj":"Ӯ ҳоло ноутбукро дуруст пайваст накардааст."},"source":"course"},"第":{"zh":"这是他的第一个工作。","p":"Zhè shì tā de dì yī ge gōngzuò.","m":{"uz":"Bu uning birinchi ishi.","ru":"Это его первая работа.","tj":"Ин кори аввалинаш аст."},"source":"course"},"箱子":{"zh":"箱子已经够重的了！","p":"Xiāngzi yǐjīng gòu zhòng de le!","m":{"uz":"Chamadon allaqachon yetarlicha og'ir bo'libdi!","ru":"Чемодан уже достаточно тяжёлый!","tj":"Ҷомадон аллакай кофӣ вазнин шудааст!"},"source":"course"},"篮球":{"zh":"你篮球打得怎么样？","p":"Nǐ lánqiú dǎ de zěnmeyàng?","m":{"uz":"Basketbolni qanday o‘ynaysan?","ru":"Как ты играешь в баскетбол?","tj":"Баскетболро чӣ хел бозӣ мекунӣ?"},"source":"course"},"紧张":{"zh":"紧张什么啊，我们都喜欢听你唱歌，你要相信自己。","p":"Jǐnzhāng shénme a, wǒmen dōu xǐhuan tīng nǐ chànggē, nǐ yào xiāngxìn zìjǐ.","m":{"uz":"Nimaga hayajonlanasan? Hammamiz qo‘shig‘ingni yoqtiramiz, o‘zingga ishon.","ru":"Чего нервничать? Нам всем нравится, как ты поёшь, поверь в себя.","tj":"Чаро асабӣ мешавӣ? Ҳама сурудхониатро дӯст медорем, ба худат бовар кун."},"source":"course"},"累":{"zh":"那会很累吧？","p":"Nà huì hěn lèi ba?","m":{"uz":"U holda juda charchagan bo'lsa kerak?","ru":"Наверное, он очень устаёт?","tj":"Пас ӯ хеле хаста мешавад?"},"source":"course"},"红绿灯":{"zh":"我发现这条路车多，红绿灯也多。","p":"Wǒ fāxiàn zhè tiáo lù chē duō, hónglǜdēng yě duō.","m":{"uz":"Payqadim, bu yo‘lda mashina ham ko‘p, svetofor ham ko‘p.","ru":"Я заметила, на этой дороге много и машин, и светофоров.","tj":"Пай бурдам, дар ин роҳ ҳам мошин зиёд аст, ҳам чароғҳои роҳнамо."},"source":"course"},"纸":{"zh":"这是今天早上的报纸吗？","p":"Zhè shì jīntiān zǎoshang de bàozhǐ ma?","m":{"uz":"Bu bugungi ertalabki gazetami?","ru":"Это сегодняшняя утренняя газета?","tj":"Ин рӯзномаи субҳи имрӯз аст?"},"source":"course"},"练":{"zh":"一般来说，学习外语需要多练习。","p":"Yìbān láishuō, xuéxí wàiyǔ xūyào duō liànxí.","m":{"uz":"Umuman olganda, chet tilini o‘rganishda ko‘p mashq qilish kerak.","ru":"Как правило, при изучении иностранного языка нужно много практиковаться.","tj":"Умуман, барои омӯхтани забони хориҷӣ бисёр машқ кардан лозим."},"source":"course"},"绿色":{"zh":"绿色的吧。","p":"Lǜsè de ba.","m":{"uz":"Yashilini.","ru":"Наверное, зелёный.","tj":"Сабзашро."},"source":"course"},"网上":{"zh":"我看了看网上的介绍。","p":"Wǒ kànle kàn wǎngshang de jièshào.","m":{"uz":"Internetdagi ma’lumotlarni bir ko‘rib chiqdim.","ru":"Я немного посмотрел информацию в интернете.","tj":"Маълумоти интернетро як назар кардам."},"source":"course"},"网球":{"zh":"我想参加网球比赛，最近一直在练习。","p":"Wǒ xiǎng cānjiā wǎngqiú bǐsài, zuìjìn yìzhí zài liànxí.","m":{"uz":"Tennis musobaqasida qatnashmoqchiman, so‘nggi paytlar doim mashq qilyapman.","ru":"Хочу участвовать в теннисном турнире, в последнее время постоянно тренируюсь.","tj":"Мехоҳам дар мусобиқаи теннис иштирок кунам, вақтҳои охир пайваста машқ мекунам."},"source":"course"},"网站":{"zh":"我给你介绍几个有用的网站。","p":"Wǒ gěi nǐ jièshào jǐ ge yǒuyòng de wǎngzhàn.","m":{"uz":"Senga bir nechta foydali saytni tavsiya qilaman.","ru":"Я покажу тебе несколько полезных сайтов.","tj":"Ба ту чанд сомонаи муфидро нишон медиҳам."},"source":"course"},"羊":{"zh":"这个星期我天天都吃羊肉。","p":"Zhège xīngqī wǒ tiāntiān dōu chī yángròu.","m":{"uz":"Bu hafta har kuni qo'y go'shti edim.","ru":"На этой неделе я ел баранину каждый день.","tj":"Ин ҳафта ман ҳар рӯз гӯшти гӯсфанд хӯрдам."},"source":"course"},"羽毛球":{"zh":"家月，你跟我们一起打羽毛球吧？","p":"Jiāyuè, nǐ gēn wǒmen yìqǐ dǎ yǔmáoqiú ba?","m":{"uz":"Jiayue, biz bilan badminton o‘ynaysanmi?","ru":"Цзяюэ, поиграешь с нами в бадминтон?","tj":"Ҷяюэ, бо мо бадминтон бозӣ мекунӣ?"},"source":"course"},"老人":{"zh":"公园里有很多老人在散步。","p":"Gōngyuán lǐ yǒu hěn duō lǎorén zài sànbù.","m":{"uz":"Parkda ko‘p keksalar sayr qilib yuribdi.","ru":"В парке гуляет много пожилых людей.","tj":"Дар боғ пиронсолони зиёд сайр мекунанд."},"source":"authored"},"老张":{"zh":"同乐，你看见老张了吗？","p":"Tónglè, nǐ kànjiàn Lǎo Zhāng le ma?","m":{"uz":"Tongle, Lao Zhangni ko‘rdingmi?","ru":"Тунлэ, ты видел Лао Чжана?","tj":"Тунлэ, Лао Чжанро дидӣ?"},"source":"course"},"考":{"zh":"我考了九十多分。","p":"Wǒ kǎo le jiǔshí duō fēn.","m":{"uz":"Men to'qson dan ortiq ball oldim.","ru":"Я набрал больше девяноста баллов.","tj":"Ман наваду чанд балл гирифтам."},"source":"course"},"而且":{"zh":"这门课不但有用，而且很有意思！","p":"Zhè mén kè búdàn yǒuyòng, érqiě hěn yǒu yìsi!","m":{"uz":"Bu kurs nafaqat foydali, balki juda qiziqarli ham!","ru":"Этот курс не только полезный, но и очень интересный!","tj":"Ин курс на танҳо муфид, балки хеле ҷолиб ҳам аст!"},"source":"course"},"耳机":{"zh":"李文，我的耳机没电了，你有充电宝吗？","p":"Lǐ Wén, wǒ de ěrjī méi diàn le, nǐ yǒu chōngdiànbǎo ma?","m":{"uz":"Li Wen, quloqchinimning quvvati tugadi, powerbanking bormi?","ru":"Ли Вэнь, мои наушники разрядились. У тебя есть пауэрбанк?","tj":"Ли Вэн, гӯшмонакам барқ надорад, пауэрбанк дорӣ?"},"source":"course"},"聊":{"zh":"那去公园走走，聊聊天儿吧。","p":"Nà qù gōngyuán zǒuzou, liáo liáotiānr ba.","m":{"uz":"Unda parkka borib sayr qilinglar, suhbatlashinglar.","ru":"Тогда сходите в парк погулять и поболтать.","tj":"Пас ба боғ рафта сайр кунед, суҳбат кунед."},"source":"course"},"聊天儿":{"zh":"那去公园走走，聊聊天儿吧。","p":"Nà qù gōngyuán zǒuzou, liáo liáotiānr ba.","m":{"uz":"Unda parkka borib sayr qilinglar, suhbatlashinglar.","ru":"Тогда сходите в парк погулять и поболтать.","tj":"Пас ба боғ рафта сайр кунед, суҳбат кунед."},"source":"course"},"联欢":{"zh":"我们班周五举行联欢。","p":"Wǒmen bān zhōuwǔ jǔxíng liánhuān.","m":{"uz":"Sinfimiz juma kuni bayram tadbiri o‘tkazadi.","ru":"В пятницу наш класс проведёт праздничный вечер.","tj":"Рӯзи ҷумъа синфи мо маҳфили идона мегузаронад."},"source":"authored"},"肉":{"zh":"好，那再加一个鸡肉，一个……","p":"Hǎo, nà zài jiā yí ge jīròu, yí ge...","m":{"uz":"Xo‘p, unda yana bitta tovuqli taom, yana bitta...","ru":"Хорошо, тогда добавим блюдо из курицы и ещё одно...","tj":"Хуб, пас боз як хӯроки мурғӣ ва яктои дигар..."},"source":"course"},"花园":{"zh":"这个一层带一个小花园，我觉得咱们可以去看看。","p":"Zhège yì céng dài yí ge xiǎo huāyuán, wǒ juéde zánmen kěyǐ qù kànkan.","m":{"uz":"Bu birinchi qavatga kichik bog‘ ham kiradi, menimcha borib ko‘rsak bo‘ladi.","ru":"У этого первого этажа есть небольшой сад, думаю, стоит посмотреть.","tj":"Ин ошёнаи якум боғи хурд ҳам дорад, ба назарам рафта дидан мумкин."},"source":"course"},"英国":{"zh":"她在英国学习汉语。","p":"Tā zài Yīngguó xuéxí Hànyǔ.","m":{"uz":"U Buyuk Britaniyada xitoy tilini o‘rganadi.","ru":"Она изучает китайский язык в Великобритании.","tj":"Ӯ дар Британияи Кабир забони чиниро меомӯзад."},"source":"authored"},"草原":{"zh":"草原一点儿也不冷。","p":"Cǎoyuán yìdiǎnr yě bù lěng.","m":{"uz":"Dasht umuman sovuq emas.","ru":"В степи совсем не холодно.","tj":"Дар саҳро тамоман хунук нест."},"source":"course"},"草地":{"zh":"孩子们在草地上踢足球。","p":"Háizimen zài cǎodì shàng tī zúqiú.","m":{"uz":"Bolalar maysazorda futbol o‘ynayapti.","ru":"Дети играют в футбол на лужайке.","tj":"Кӯдакон дар майсазор футбол бозӣ мекунанд."},"source":"authored"},"药店":{"zh":"药店在医院旁边。","p":"Yàodiàn zài yīyuàn pángbiān.","m":{"uz":"Dorixona shifoxona yonida.","ru":"Аптека находится рядом с больницей.","tj":"Дорухона дар паҳлуи беморхона аст."},"source":"authored"},"行李":{"zh":"你的行李箱是什么样的？","p":"Nǐ de xínglixiāng shì shénme yàng de?","m":{"uz":"Chamadoning qanday ko‘rinishda?","ru":"Как выглядит твой чемодан?","tj":"Ҷомадонат чӣ хел аст?"},"source":"course"},"街":{"zh":"我经过那条街道来的。","p":"Wǒ jīngguò nà tiáo jiēdào lái de.","m":{"uz":"Men u ko'cha orqali keldim.","ru":"Я пришёл через ту улицу.","tj":"Ман аз он кӯча гузашта омадам."},"source":"course"},"西北":{"zh":"我家在城市的西北边。","p":"Wǒ jiā zài chéngshì de xīběi biān.","m":{"uz":"Uyimiz shaharning shimoli-g‘arbida.","ru":"Мой дом находится на северо-западе города.","tj":"Хонаи мо дар шимолу ғарби шаҳр аст."},"source":"authored"},"见":{"zh":"好，再见！","p":"Hǎo, zàijiàn!","m":{"uz":"Xo‘p, xayr!","ru":"Хорошо, до свидания!","tj":"Хуб, хайр!"},"source":"course"},"视频":{"zh":"我刚刚看视频学会了包饺子。","p":"Wǒ gānggāng kàn shìpín xuéhuì le bāo jiǎozi.","m":{"uz":"Men hozirgina video ko‘rib jiaozi tugishni o‘rgandim.","ru":"Я только что научился лепить цзяоцзы по видео.","tj":"Ман ҳозиргина видео дида ҷяози печониданро омӯхтам."},"source":"course"},"认得":{"zh":"它就好像我们的孩子，我们照顾它，它也认得我们了。","p":"Tā jiù hǎoxiàng wǒmen de háizi, wǒmen zhàogù tā, tā yě rènde wǒmen le.","m":{"uz":"U xuddi farzandimizdek: biz unga qaraymiz, u ham bizni taniydi.","ru":"Она словно наш ребёнок: мы заботимся о ней, и она уже узнаёт нас.","tj":"Он мисли фарзанди мост: мо нигоҳубинаш мекунем ва ӯ ҳам моро мешиносад."},"source":"course"},"记":{"zh":"明天会下雨，记得带伞！","p":"Míngtiān huì xiàyǔ, jìde dài sǎn!","m":{"uz":"Ertaga yomg'ir yog'sa kerak, soyabon olishni yodda tuting!","ru":"Завтра, наверное, будет дождь — возьмите зонт!","tj":"Фардо шояд борон борад, чатр гиред!"},"source":"course"},"词":{"zh":"这些词要好好看看。","p":"Zhèxiē cí yào hǎohāo kànkan.","m":{"uz":"Bu so‘zlarni yaxshilab ko‘rib chiqish kerak.","ru":"Эти слова нужно как следует повторить.","tj":"Ин калимаҳоро хуб дида баромадан лозим."},"source":"course"},"该":{"zh":"八点了，该上课了。","p":"Bā diǎn le, gāi shàngkè le.","m":{"uz":"Soat sakkiz bo‘ldi, darsni boshlash vaqti keldi.","ru":"Уже восемь, пора на занятия.","tj":"Соат ҳашт шуд, вақти дарс расид."},"source":"course"},"请客":{"zh":"今天我请客，你们想吃什么就点什么！","p":"Jīntiān wǒ qǐngkè, nǐmen xiǎng chī shénme jiù diǎn shénme!","m":{"uz":"Bugun men mehmon qilaman, nima yegingiz kelsa, o‘shani buyurtma qilinglar!","ru":"Сегодня угощаю я, заказывайте что хотите!","tj":"Имрӯз ман меҳмон мекунам, ҳар чӣ хоҳед фармоиш диҳед!"},"source":"course"},"请问":{"zh":"请问，今天几号？","p":"Qǐngwèn, jīntiān jǐ hào?","m":{"uz":"Kechirasiz, bugun nechanchi sana?","ru":"Извините, какое сегодня число?","tj":"Бубахшед, имрӯз чанди сана аст?"},"source":"course"},"读书":{"zh":"他们读书呢。","p":"Tāmen dú shū ne.","m":{"uz":"Ular hozir kitob o‘qishyapti.","ru":"Они сейчас читают.","tj":"Онҳо ҳоло китоб мехонанд."},"source":"course"},"走路":{"zh":"可以坐缆车或者走路上去。","p":"Kěyǐ zuò lǎnchē huòzhě zǒulù shàngqù.","m":{"uz":"Kanatli aravacha bilan yoki piyoda chiqish mumkin.","ru":"Можно подняться на фуникулёре или пешком.","tj":"Метавонед бо канаткаш ё пиёда боло равед."},"source":"course"},"起":{"zh":"对不起。","p":"Duìbuqǐ.","m":{"uz":"Kechirasiz.","ru":"Извините.","tj":"Бубахшед."},"source":"course"},"足球":{"zh":"你喜欢踢足球吗？","p":"Nǐ xǐhuan tī zúqiú ma?","m":{"uz":"Futbol o'ynashni yaxshi ko'rasanmi?","ru":"Тебе нравится играть в футбол?","tj":"Оё ту футбол бозӣ кардан ро дӯст медорӣ?"},"source":"course"},"跑":{"zh":"她跑出去了。","p":"Tā pǎo chū qù le.","m":{"uz":"U yugurib chiqib ketdi.","ru":"Она выбежала (туда).","tj":"Вай давон баромад (он ҷо)."},"source":"course"},"路上":{"zh":"可以坐缆车或者走路上去。","p":"Kěyǐ zuò lǎnchē huòzhě zǒulù shàngqù.","m":{"uz":"Kanatli aravacha bilan yoki piyoda chiqish mumkin.","ru":"Можно подняться на фуникулёре или пешком.","tj":"Метавонед бо канаткаш ё пиёда боло равед."},"source":"course"},"跳":{"zh":"他高兴得跳起来了！","p":"Tā gāoxìng de tiào qǐlái le!","m":{"uz":"U shu qadar xurshandki, sakrab ketdi!","ru":"Он так обрадовался, что подпрыгнул!","tj":"Вай ончунон хурсанд шуд, ки ҷаҳид!"},"source":"course"},"踢":{"zh":"你踢得怎么样？","p":"Nǐ tī de zěnmeyàng?","m":{"uz":"Qanday o‘ynaysan?","ru":"Как ты играешь?","tj":"Чӣ хел бозӣ мекунӣ?"},"source":"course"},"身边":{"zh":"它身边那只熊猫半天没动，是不是在睡觉呢？","p":"Tā shēnbiān nà zhī xióngmāo bàntiān méi dòng, shì bú shì zài shuìjiào ne?","m":{"uz":"Yonidagi panda ancha vaqtdan beri qimirlamadi, uxlayaptimi?","ru":"Панда рядом уже долго не двигается. Она спит?","tj":"Пандаи паҳлӯяш муддати зиёд ҳаракат накардааст, хоб аст?"},"source":"course"},"身高":{"zh":"是长得有点儿像，但是他比同乐高，身高有一米八。","p":"Shì zhǎng de yǒudiǎnr xiàng, dànshì tā bǐ Tónglè gāo, shēngāo yǒu yì mǐ bā.","m":{"uz":"Ha, biroz o‘xshash, lekin u Tongledan balandroq, bo‘yi bir metr sakson.","ru":"Да, внешне немного похожи, но он выше Тунлэ — рост около метра восьмидесяти.","tj":"Ҳа, каме монанданд, аммо ӯ аз Тунлэ баландтар аст, қадаш як метру ҳаштод."},"source":"course"},"车站":{"zh":"有，但车站有点儿远。","p":"Yǒu, dàn chēzhàn yǒudiǎnr yuǎn.","m":{"uz":"Bor, lekin bekat biroz uzoq.","ru":"Есть, но остановка немного далеко.","tj":"Ҳаст, аммо истгоҳ каме дур аст."},"source":"course"},"边":{"zh":"有，杯子在这边。","p":"Yǒu, bēizi zài zhèbiān.","m":{"uz":"Ha, piyolalar bu yerda.","ru":"Да, чашки здесь.","tj":"Ҳа, пиёлаҳо ин ҷоанд."},"source":"course"},"过年":{"zh":"我要在中国过年，真开心。","p":"Wǒ yào zài Zhōngguó guònián, zhēn kāixīn.","m":{"uz":"Xitoyda Yangi yilni o‘tkazaman, juda xursandman.","ru":"Я буду встречать Новый год в Китае, очень радуюсь.","tj":"Ман Соли навро дар Чин мегузаронам, хеле хушҳолам."},"source":"course"},"过来":{"zh":"你把水果拿过来。","p":"Nǐ bǎ shuǐguǒ ná guò lái.","m":{"uz":"Mevalarni bu yerga olib keling.","ru":"Принеси фрукты сюда.","tj":"Меваҳоро ин ҷо биёр."},"source":"course"},"过节":{"zh":"你们怎样过节？","p":"Nǐmen zěnyàng guòjié?","m":{"uz":"Sizlar bayramni qanday nishonlaysizlar?","ru":"Как вы отмечаете праздник?","tj":"Шумо идро чӣ тавр ҷашн мегиред?"},"source":"course"},"运动会":{"zh":"是啊！你打算参加运动会吗？","p":"Shì a! Nǐ dǎsuàn cānjiā yùndònghuì ma?","m":{"uz":"Ha! Sen ham sport musobaqasida qatnashmoqchimisan?","ru":"Да! Ты собираешься участвовать в соревнованиях?","tj":"Ҳа! Ту ҳам дар мусобиқа иштирок карданӣ ҳастӣ?"},"source":"course"},"运动员":{"zh":"运动员刘长春参加了奥运会。","p":"Yùndòngyuán Liú Chángchūn cānjiā le Àoyùnhuì.","m":{"uz":"Sportchi Liu Changchun Olimpiya o‘yinlarida qatnashgan.","ru":"Спортсмен Лю Чанчунь участвовал в Олимпийских играх.","tj":"Варзишгар Лю Чанчун дар Бозиҳои олимпӣ иштирок кард."},"source":"authored"},"这个":{"zh":"我买这个吧。","p":"Wǒ mǎi zhège ba.","m":{"uz":"Men mana bunisini olaman.","ru":"Я возьму эту.","tj":"Ман ҳаминро мегирам."},"source":"course"},"这么":{"zh":"怎么点这么多菜？","p":"Zěnme diǎn zhème duō cài?","m":{"uz":"Nega buncha ko‘p taom buyurtma qilding?","ru":"Зачем заказал столько блюд?","tj":"Чаро ин қадар хӯрок фармоиш додӣ?"},"source":"course"},"这样":{"zh":"好极了！就这样做！","p":"Hǎo jí le! Jiù zhèyàng zuò!","m":{"uz":"Zo'r! Xuddi shunday qiling!","ru":"Отлично! Именно так и делайте!","tj":"Олӣ! Маҳз ҳамин тавр кунед!"},"source":"course"},"这边":{"zh":"有，杯子在这边。","p":"Yǒu, bēizi zài zhèbiān.","m":{"uz":"Ha, piyolalar bu yerda.","ru":"Да, чашки здесь.","tj":"Ҳа, пиёлаҳо ин ҷоанд."},"source":"course"},"这里":{"zh":"这里有几个杯子。","p":"Zhèlǐ yǒu jǐ ge bēizi.","m":{"uz":"Bu yerda bir nechta qadah bor.","ru":"Здесь есть несколько стаканов.","tj":"Инҷо чанд косача вуҷуд дорад."},"source":"course"},"进去":{"zh":"我们进去看看吧。","p":"Wǒmen jìnqu kànkan ba.","m":{"uz":"Ichkariga kirib ko‘raylik.","ru":"Давай зайдём и посмотрим.","tj":"Биё даромада тамошо кунем."},"source":"course"},"进来":{"zh":"他走进来了。","p":"Tā zǒu jìn lái le.","m":{"uz":"U yurib kirib keldi.","ru":"Он вошёл пешком.","tj":"Вай пиёда даромад."},"source":"course"},"选":{"zh":"宾馆也选好了吗？","p":"Bīnguǎn yě xuǎn hǎo le ma?","m":{"uz":"Mehmonxonani ham tanlab bo‘ldingmi?","ru":"Гостиницу тоже выбрали?","tj":"Меҳмонхонаро ҳам интихоб кардед?"},"source":"course"},"遇见":{"zh":"昨天我在路上遇见了老师。","p":"Zuótiān wǒ zài lùshang yùjiàn le lǎoshī.","m":{"uz":"Kecha yo‘lda ustozimni uchratdim.","ru":"Вчера я встретил преподавателя по дороге.","tj":"Ман дирӯз дар роҳ устодро вохӯрдам."},"source":"authored"},"那个":{"zh":"那个苹果好吃。","p":"Nàge píngguǒ hǎochī.","m":{"uz":"O‘sha olma mazali.","ru":"То яблоко вкусное.","tj":"Он себ болаззат аст."},"source":"course"},"那么":{"zh":"今天没有昨天那么冷。","p":"Jīntiān méiyǒu zuótiān nàme lěng.","m":{"uz":"Bugun kecha kabi sovuq emas.","ru":"Сегодня не так холодно, как вчера.","tj":"Имрӯз ба монанди дирӯз сард нест."},"source":"course"},"那些":{"zh":"这些五块钱一个，那些十块钱一个。","p":"Zhèxiē wǔ kuài qián yí ge, nàxiē shí kuài qián yí ge.","m":{"uz":"Bularning bittasi 5 yuan, anavilarning bittasi 10 yuan.","ru":"Эти по 5 юаней, а те по 10 юаней.","tj":"Инҳо яктоӣ 5 юан, онҳо яктоӣ 10 юан."},"source":"course"},"那样":{"zh":"好，那样我们就都有新年礼物了！","p":"Hǎo, nàyàng wǒmen jiù dōu yǒu xīnnián lǐwù le!","m":{"uz":"Xo‘p, shunda ikkalamizda ham Yangi yil sovg‘asi bo‘ladi!","ru":"Хорошо, тогда у нас обеих будут новогодние подарки!","tj":"Хуб, он гоҳ ҳардуямон тӯҳфаи Соли нав дорем!"},"source":"course"},"那边":{"zh":"好吧，我们再去那边看看。","p":"Hǎo ba, wǒmen zài qù nàbian kànkan.","m":{"uz":"Mayli, yana u tomonga borib ko‘raylik.","ru":"Ладно, давай посмотрим ещё там.","tj":"Хуб, боз он тараф рафта бинем."},"source":"course"},"那里":{"zh":"还睡呢？他今天去不去那里？","p":"Hái shuì ne? Tā jīntiān qù bu qù nàli?","m":{"uz":"Hali uxlayaptimi? U bugun u yerga boradimi yo‘qmi?","ru":"Всё ещё спит? Он сегодня пойдёт туда или нет?","tj":"Ҳанӯз хоб аст? Ӯ имрӯз ба он ҷо меравад ё не?"},"source":"course"},"邮件":{"zh":"您没看到邮件吗？经理还没回来呢，下周才能开会。","p":"Nín méi kàndào yóujiàn ma? Jīnglǐ hái méi huílái ne, xià zhōu cái néng kāihuì.","m":{"uz":"Emailni ko‘rmadingizmi? Menejer hali qaytmadi, yig‘ilish faqat keyingi hafta bo‘ladi.","ru":"Вы не видели письмо? Менеджер ещё не вернулся, совещание будет только на следующей неделе.","tj":"Email-ро надидед? Мудир ҳоло барнагаштааст, ҷаласа танҳо ҳафтаи оянда мешавад."},"source":"course"},"邮箱":{"zh":"请把邮件发到我的邮箱。","p":"Qǐng bǎ yóujiàn fā dào wǒ de yóuxiāng.","m":{"uz":"Iltimos, xatni elektron pochtamga yuboring.","ru":"Пожалуйста, отправьте письмо на мою электронную почту.","tj":"Лутфан, номаро ба почтаи электронии ман фиристед."},"source":"authored"},"酒":{"zh":"怎么还买红酒回来了？谁喝啊？","p":"Zěnme hái mǎi hóngjiǔ huílai le? Shéi hē a?","m":{"uz":"Nega vino ham sotib olib kelding? Kim ichadi?","ru":"Зачем ещё купил вино? Кто будет пить?","tj":"Чаро боз шароб харида овардӣ? Кӣ менӯшад?"},"source":"course"},"酒店":{"zh":"这家酒店离车站很近。","p":"Zhè jiā jiǔdiàn lí chēzhàn hěn jìn.","m":{"uz":"Bu mehmonxona bekatga juda yaqin.","ru":"Этот отель находится очень близко к станции.","tj":"Ин меҳмонхона ба истгоҳ хеле наздик аст."},"source":"authored"},"里面":{"zh":"房间里面热得很。","p":"Fángjiān lǐmian rè de hěn.","m":{"uz":"Xonaning ichi juda issiq.","ru":"В комнате очень жарко.","tj":"Даруни ҳуҷра хеле гарм аст."},"source":"course"},"野生":{"zh":"全世界只有中国有野生大熊猫，中国是大熊猫的家。","p":"Quán shìjiè zhǐ yǒu Zhōngguó yǒu yěshēng dàxióngmāo, Zhōngguó shì dàxióngmāo de jiā.","m":{"uz":"Butun dunyoda yovvoyi katta pandalar faqat Xitoyda bor, Xitoy — pandalarning vatani.","ru":"Во всём мире дикие большие панды есть только в Китае; Китай — их родина.","tj":"Дар тамоми ҷаҳон пандаҳои ваҳшии калон танҳо дар Чин ҳастанд; Чин ватани онҳост."},"source":"course"},"门口":{"zh":"门口有家奶茶店。你想喝杯奶茶吗？","p":"Ménkǒu yǒu jiā nǎichádiàn. Nǐ xiǎng hē bēi nǎichá ma?","m":{"uz":"Kirishda sutli choy do‘koni bor. Bir piyola sutli choy ichasanmi?","ru":"У входа есть магазин молочного чая. Хочешь чашку?","tj":"Дар назди даромадгоҳ дӯкони чойи ширӣ ҳаст. Як пиёла мехоҳӣ?"},"source":"course"},"门票":{"zh":"你先去买门票，再来这里找我。","p":"Nǐ xiān qù mǎi ménpiào, zài lái zhèlǐ zhǎo wǒ.","m":{"uz":"Avval kirish chiptasini ol, keyin bu yerga meni topgani kel.","ru":"Сначала купи билет, потом приходи сюда ко мне.","tj":"Аввал чипта бихар, баъд ин ҷо назди ман биё."},"source":"course"},"间":{"zh":"我去洗手间。","p":"Wǒ qù xǐshǒujiān.","m":{"uz":"Hojatxonaga boraman.","ru":"Я иду в туалет.","tj":"Ба ҳоҷатхона меравам."},"source":"course"},"难看":{"zh":"这件衣服的颜色太难看了。","p":"Zhè jiàn yīfu de yánsè tài nánkàn le.","m":{"uz":"Bu kiyimning rangi juda xunuk.","ru":"Цвет этой одежды очень некрасивый.","tj":"Ранги ин либос хеле бад аст."},"source":"authored"},"难题":{"zh":"这道难题我终于做出来了。","p":"Zhè dào nántí wǒ zhōngyú zuò chūlái le.","m":{"uz":"Nihoyat, bu murakkab masalani yechdim.","ru":"Наконец я решил эту трудную задачу.","tj":"Ниҳоят ин масъалаи душворро ҳал кардам."},"source":"authored"},"雨":{"zh":"下雨了。","p":"Xià yǔ le.","m":{"uz":"Yomg‘ir yog‘di.","ru":"Пошёл дождь.","tj":"Борон борид."},"source":"course"},"雨衣":{"zh":"我可以借给你，我车里有一把伞和一件雨衣。","p":"Wǒ kěyǐ jiè gěi nǐ, wǒ chē lǐ yǒu yì bǎ sǎn hé yí jiàn yǔyī.","m":{"uz":"Men senga berib turaman, mashinamda bitta soyabon va yomg‘irpo‘sh bor.","ru":"Я могу тебе одолжить: в машине есть зонт и дождевик.","tj":"Ман ба ту медиҳам, дар мошинам як чатр ва як боронӣ ҳаст."},"source":"course"},"面":{"zh":"书包在门后面。","p":"Shūbāo zài mén hòumian.","m":{"uz":"Sumka eshik orqasida.","ru":"Рюкзак за дверью.","tj":"Ҷузвдон пушти дар аст."},"source":"course"},"面前":{"zh":"她面前放着一杯茶。","p":"Tā miànqián fàngzhe yì bēi chá.","m":{"uz":"Uning oldida bir piyola choy turibdi.","ru":"Перед ней стоит чашка чая.","tj":"Дар пеши ӯ як пиёла чой гузошта шудааст."},"source":"authored"},"面条儿":{"zh":"长长的面条儿，大大的蛋糕。","p":"Chángcháng de miàntiáor, dàdà de dàngāo.","m":{"uz":"Uzun-uzun lag‘mon va katta-katta tort.","ru":"Длинная-длинная лапша и большой-большой торт.","tj":"Угрои дароз-дароз ва торти калон-калон."},"source":"course"},"鞋":{"zh":"谢谢你们来看我女儿。你送的小皮鞋和小帽子真漂亮！","p":"Xièxie nǐmen lái kàn wǒ nǚ'ér. Nǐ sòng de xiǎo píxié hé xiǎo màozi zhēn piàoliang!","m":{"uz":"Qizimni ko'rgani kelganingiz uchun rahmat. Siz sovg'a qilgan kichik charm tufli va kichik shlyapa juda chiroyli!","ru":"Спасибо, что пришли посмотреть мою дочь. Маленькие кожаные туфельки и шапочка, которые ты подарила, очень красивые!","tj":"Ташаккур, ки духтарамро дидан омадед. Пойафзоли чармии хурд ва кулоҳи хурде, ки ту додӣ, хеле зебо аст!"},"source":"course"},"风":{"zh":"怎么突然刮起风来了？","p":"Zěnme tūrán guā qǐ fēng lái le?","m":{"uz":"Nega birdan shamol esa boshladi?","ru":"Почему вдруг поднялся ветер?","tj":"Чаро ногаҳон шамол вазидан гирифт?"},"source":"course"},"飞":{"zh":"喂，一飞！","p":"Wèi, Yīfēi!","m":{"uz":"Allo, Yifei!","ru":"Привет, Ифэй!","tj":"Алло, Ифэй!"},"source":"course"},"饭":{"zh":"做饭啊。","p":"Zuò fàn a.","m":{"uz":"Ovqat pishirish-da.","ru":"Готовкой еды.","tj":"Хӯрокпазӣ."},"source":"course"},"饭馆":{"zh":"这家饭馆的菜挺好吃的。","p":"Zhè jiā fànguǎn de cài tǐng hǎochī de.","m":{"uz":"Bu restoranning taomlari ancha mazali.","ru":"В этом ресторане блюда довольно вкусные.","tj":"Хӯрокҳои ин тарабхона хеле болаззатанд."},"source":"course"},"饺子":{"zh":"我要一斤饺子。","p":"Wǒ yào yì jīn jiǎozi.","m":{"uz":"Menga bir jin jiaozi bering.","ru":"Я возьму один цзинь цзяоцзы.","tj":"Ман як ҷин ҷяозы мегирам."},"source":"course"},"马路":{"zh":"过马路时请小心。","p":"Guò mǎlù shí qǐng xiǎoxīn.","m":{"uz":"Yo‘lni kesib o‘tayotganda ehtiyot bo‘ling.","ru":"Переходя дорогу, будьте осторожны.","tj":"Ҳангоми гузаштан аз роҳ эҳтиёт кунед."},"source":"authored"},"高中":{"zh":"想提高中文水平要多听多看，更要多说多练。","p":"Xiǎng tígāo Zhōngwén shuǐpíng yào duō tīng duō kàn, gèng yào duō shuō duō liàn.","m":{"uz":"Xitoy tilini yaxshilash uchun ko‘p tinglash va o‘qish kerak, undan ham muhimi ko‘p gapirib, mashq qilish kerak.","ru":"Чтобы повысить уровень китайского, нужно больше слушать и читать, а ещё важнее — больше говорить и практиковаться.","tj":"Барои беҳтар кардани чинӣ бисёр шунидану хондан лозим, боз ҳам бештар гуфтану машқ кардан даркор."},"source":"course"},"高铁":{"zh":"行！怎么买高铁票？","p":"Xíng! Zěnme mǎi gāotiě piào?","m":{"uz":"Bo‘ladi! Tezyurar poyezd chiptasini qanday olamiz?","ru":"Хорошо! Как купить билет на скоростной поезд?","tj":"Мешавад! Чиптаи қатораи баландсуръатро чӣ тавр мехарем?"},"source":"course"},"鸡":{"zh":"好，那再加一个鸡肉，一个……","p":"Hǎo, nà zài jiā yí ge jīròu, yí ge...","m":{"uz":"Xo‘p, unda yana bitta tovuqli taom, yana bitta...","ru":"Хорошо, тогда добавим блюдо из курицы и ещё одно...","tj":"Хуб, пас боз як хӯроки мурғӣ ва яктои дигар..."},"source":"course"},"黄色":{"zh":"你看我穿这条黄色的短裤好看吗？","p":"Nǐ kàn wǒ chuān zhè tiáo huángsè de duǎnkù hǎokàn ma?","m":{"uz":"Qara, mana bu sariq shortik menga yarashadimi?","ru":"Посмотри, мне идут эти жёлтые шорты?","tj":"Бин, ин шорти зард ба ман зебо меистад?"},"source":"course"},"黑色":{"zh":"你看这条黑色的怎么样？","p":"Nǐ kàn zhè tiáo hēisè de zěnmeyàng?","m":{"uz":"Bu qora shim qanday?","ru":"Как тебе эти чёрные брюки?","tj":"Ин шими сиёҳ чӣ хел?"},"source":"course"}};
